INSERT OR IGNORE INTO catalog_entities(kind,slug,name,status,category_slug,sort_order,content_json) VALUES ('program','germany-university-pathway','University Pathway','active','adult-academic',1,'{"order":1,"id":"germany-university-pathway","category_slug":"adult-academic","name":"University Pathway","image":"/images/germ_1.webp","ages":{"min":"17","max":"99"},"duration":12,"price":"€8,000","color":"secondary","badges":["Academic","Year-Round"],"highlights":["Prepare for university entry","Studienkolleg prep course","TestDaf prep","Guidance through every step"],"description":"<p>The University Pathway programme aims to help students prepare for the academic and language demands of studying in Germany. It brings together German language preparation, Studienkolleg preparation and entrance examination study, giving students a clearer understanding of the steps towards university entry.</p><p>The programme connects language development with academic preparation. Students work towards communicating more confidently in German while becoming familiar with the expectations of further study and the preparation required for the TestDaF examination.</p><p>Our approach encourages steady progress, independent study and purposeful preparation. Students are encouraged to identify the areas they need to strengthen, organise their learning and approach unfamiliar academic tasks with greater confidence.</p><p>Throughout the programme, the focus remains on building a sound foundation for the next stage of education. Language practice and entrance examination preparation support students as they work towards their chosen university pathway.</p>","status":"active","gallery":[],"includes":[],"excludes":[],"schedule":[],"tagline":"","level":""}');
INSERT OR IGNORE INTO catalog_entities(kind,slug,name,status,category_slug,sort_order,content_json) VALUES ('program','usa-pre-university','Pre-University Camp','inactive','adult-academic',2,'{"order":2,"id":"usa-pre-university","category_slug":"adult-academic","name":"Pre-University Camp","image":"/images/usa_3.webp","ages":{"min":16,"max":18},"duration":4,"price":"$5,200","color":"primary","badges":["Academic","University Prep"],"highlights":["Experience university life","SAT/ACT prep sessions","College application workshops","Campus tours in Boston or LA"],"description":"<p>The Pre-University Camp aims to introduce students to university life in the United States while helping them prepare for the application process. Time on a US college campus gives students an opportunity to explore their interests and consider what they want from their future studies.</p><p>The programme combines SAT and ACT preparation sessions with college application workshops. Students explore the different elements of an application and consider how to communicate their interests, experiences and academic goals clearly.</p><p>Our approach connects preparation with first-hand experience of a university environment. Campus tours in Boston or Los Angeles help students place their plans in context, while encouraging curiosity, independence and thoughtful decision-making.</p><p>Throughout the camp, students focus on understanding their options, strengthening their preparation and becoming more comfortable with the transition to university. The aim is to help them approach their next steps with a clearer sense of direction.</p>","status":"inactive","gallery":["/images/usa_1.webp","/images/usa_2.webp","/images/usa_3.webp"]}');
INSERT OR IGNORE INTO catalog_entities(kind,slug,name,status,category_slug,sort_order,content_json) VALUES ('program','uk-young-professional','Young Professional Summer','inactive','adult-academic',3,'{"order":3,"id":"uk-young-professional","category_slug":"adult-academic","name":"Young Professional Summer","tagline":"A unique blend of English and subject-specific learning alongside real-world industry experience.","image":"","ages":{"min":13,"max":17},"duration":2,"level":"Professional","price":null,"color":"secondary","badges":["Career","Immersive"],"highlights":["Explore various career paths like AI, Engineering, and Business.","Real-world industry experience.","Improve language skills and knowledge in a professional context.","Designed for ambitious individuals."],"description":"<p>The Young Professional Summer programme aims to help ambitious students explore future career interests while developing their English. This two-week experience brings together language learning, subject study and exposure to the world of work, allowing students to consider how their interests might develop beyond school.</p><p>Students explore areas such as Business, Engineering, Artificial Intelligence and Visual Arts. English is used within a professional context, helping students connect vocabulary and communication skills with the subjects and industries that interest them.</p><p>Our approach links learning with practical relevance. Students are encouraged to ask questions, explain their ideas and consider the skills different careers require, while developing confidence in using English for more than everyday conversation.</p><p>Throughout the programme, the focus is on broadening knowledge and making informed choices. Students can explore unfamiliar fields, strengthen their communication and begin to recognise the areas they would like to pursue in greater depth.</p>","includes":[],"excludes":[],"status":"inactive","gallery":[]}');
INSERT OR IGNORE INTO catalog_entities(kind,slug,name,status,category_slug,sort_order,content_json) VALUES ('program','uk-pre-university','Adult Pre-University','inactive','adult-academic',4,'{"order":4,"id":"uk-pre-university","category_slug":"adult-academic","name":"Adult Pre-University","tagline":"Equipping dedicated students with the skills needed for university-level studies.","image":"","ages":{"min":15,"max":17},"duration":2,"level":"Advanced","price":null,"color":"accent","badges":["Academic","University Prep"],"highlights":["Interactive lessons, guest lectures, and debate societies.","Develop a strong foundation in your field of interest.","Personalised feedback and support from expert instructors.","Navigate the transition to higher education successfully."],"description":"<p>The Adult Pre-University programme aims to prepare dedicated students for the expectations of university-level study. Over two weeks, students explore their academic interests while developing the confidence and learning habits needed for the transition to higher education.</p><p>Expert instructors guide students through interactive lessons, masterclasses and debate societies. These activities encourage students to engage with ideas actively, ask thoughtful questions and develop a stronger foundation in their chosen field.</p><p>Our approach combines subject knowledge with independent thinking and clear communication. Personalised feedback helps students recognise their strengths, identify areas for improvement and reflect on how they approach unfamiliar academic challenges.</p><p>Throughout the programme, students practise discussing ideas, supporting their opinions and responding constructively to different perspectives. The emphasis is on becoming a more engaged and reflective learner, with a clearer understanding of what university study involves.</p>","includes":[],"excludes":[],"status":"inactive","gallery":[]}');
INSERT OR IGNORE INTO catalog_entities(kind,slug,name,status,category_slug,sort_order,content_json) VALUES ('program','italy-junior-discovery','Junior Discovery','active','kids-camps',2,'{"order":2,"id":"italy-junior-discovery","category_slug":"kids-camps","name":"Junior Discovery","tagline":"Empowering students to explore their potential through experiential education and blending culture, and adventure.","image":"/images/Junior_1.webp","ages":{"min":"12","max":"16"},"duration":0,"level":"","price":"","color":"success","badges":["New","Explorer"],"highlights":["Empowering students to explore their potential through experiential education.","Innovative summer programs blending education, culture, and adventure.","Camp is entirely conducted in English.","Develop independence, form new friendships, strengthen communication skills, and learn the value of teamwork."],"description":"<p>The Junior Discovery programme aims to help young people explore their interests through a combination of education, culture and adventure in Italy. Conducted entirely in English, the camp creates opportunities to learn through experience while sharing daily life with other students.</p><p>Activities bring learning beyond the classroom, encouraging campers to take part, communicate and try something unfamiliar. Cultural discovery and shared experiences give students practical reasons to use English and connect with the people around them.</p><p>Our approach places personal development alongside exploration. Campers are encouraged to make decisions, contribute to their group and recognise the value of working together, while gradually building independence and confidence.</p><p>Throughout the camp, the focus is on strengthening communication, developing teamwork and forming new friendships. Students are supported in expressing their individuality, approaching new experiences with curiosity and discovering what they can contribute to a shared adventure.</p>","includes":[],"excludes":[],"status":"active","schedule":[],"gallery":[]}');
INSERT OR IGNORE INTO catalog_entities(kind,slug,name,status,category_slug,sort_order,content_json) VALUES ('program','germany-german-language-course','German Language Course','active','language-and-activity-camps',1,'{"order":1,"id":"germany-german-language-course","category_slug":"language-and-activity-camps","name":"German Language Course","tagline":"Learn German through immersive study, practical communication and flexible course formats.","image":"/images/germany_2.webp","ages":{"min":null,"max":null},"duration":null,"level":"All Levels","price":null,"color":"primary","badges":["Language","German"],"highlights":["Summer Camps","Winter Camps","Online Courses","Exam Preparation"],"description":"<p>The German Language Course aims to help children, teenagers and adults develop the language skills they need for their own goals. With selected locations across Germany and Austria, the programme connects German study with opportunities to experience the language in a cultural setting.</p><p>Students can choose from Summer Camps, Winter Camps, Online Courses and Exam Preparation. These formats offer different ways to study, allowing learners to consider their current level, availability and reasons for learning German.</p><p>Our approach connects speaking, listening, reading and writing with practical communication. Students are encouraged to develop understanding as well as accuracy, building the confidence to use what they learn beyond individual classroom exercises.</p><p>Throughout their chosen course, learners focus on strengthening their foundations and extending their ability to communicate. Whether preparing for an examination or developing everyday language skills, the aim is to make German a more useful and familiar part of their lives.</p>","includes":[],"excludes":[],"status":"active","schedule":[],"gallery":[]}');
INSERT OR IGNORE INTO catalog_entities(kind,slug,name,status,category_slug,sort_order,content_json) VALUES ('program','germany-children-summer','Children Summer Camps','inactive','kids-camps',3,'{"order":3,"id":"germany-children-summer","category_slug":"kids-camps","name":"Children Summer Camps","image":"/images/germany_2.webp","ages":{"min":8,"max":14},"duration":2,"price":"€2,200","color":"primary","badges":["Language","Summer"],"highlights":["Intensive German lessons","Afternoon activities","Cultural excursions","Safe, supervised environment"],"description":"<p>The Children Summer Camps aim to introduce young learners to German through a combination of language lessons, activities and cultural discovery. The programme gives children an opportunity to develop their understanding of the language while spending time with international peers.</p><p>Intensive German lessons provide the foundation for learning. Afternoon activities and cultural excursions extend the experience, helping children connect the language they study with the places they visit and the people they meet.</p><p>Our approach brings learning and participation together in a supervised environment. Children are encouraged to join in, communicate and become more comfortable with unfamiliar words and situations while enjoying the social experience of camp.</p><p>Throughout the programme, the focus is on building language confidence, discovering German culture and developing friendships. Shared activities give children opportunities to cooperate, express themselves and see language as a practical part of everyday life.</p>","status":"inactive","gallery":[]}');
INSERT OR IGNORE INTO catalog_entities(kind,slug,name,status,category_slug,sort_order,content_json) VALUES ('program','spain-language-water-sports','Language & Water Sports','inactive','language-and-activity-camps',1,'{"order":1,"id":"spain-language-water-sports","category_slug":"language-and-activity-camps","name":"Language & Water Sports","image":"/images/spain_1_g.webp","ages":{"min":10,"max":17},"duration":2,"price":"€2,600","color":"secondary","badges":["Popular","Summer"],"highlights":["Spanish or English classes","Sailing & Windsurfing","Paddle Surfing & Kayaking","Beach activities"],"description":"<p>The Language &amp; Water Sports programme aims to combine language development with an active experience on the Spanish coast. Students can study Spanish or English while taking part in water sports that bring movement, discovery and shared challenges into their day.</p><p>Language classes are complemented by sailing, windsurfing, paddle surfing and kayaking. This combination allows students to move between focused study and outdoor activity, exploring different ways to learn and participate.</p><p>Our approach connects communication with cooperation. Students are encouraged to listen carefully, express themselves clearly and contribute to shared activities, developing confidence both in their chosen language and in their approach to new experiences.</p><p>Throughout the programme, beach activities and water sports provide opportunities to practise coordination, concentration and teamwork. The emphasis is on taking an active part in camp life while enjoying the balance of language learning and time by the sea.</p>","status":"inactive","gallery":["/images/spain_1_g.webp","/images/spain_2_g.webp","/images/spain_3_g.webp","/images/spain_4_g.webp","/images/spain_5_g.webp","/images/spain_6_g.webp"]}');
INSERT OR IGNORE INTO catalog_entities(kind,slug,name,status,category_slug,sort_order,content_json) VALUES ('program','canada-english-ski','English & Ski (Winter)','inactive','language-and-activity-camps',2,'{"order":2,"id":"canada-english-ski","category_slug":"language-and-activity-camps","name":"English & Ski (Winter)","image":"/images/canada_3.webp","ages":{"min":13,"max":18},"duration":2,"price":"$4,100","color":"primary","badges":["Winter","Sports","Language"],"highlights":["Morning English classes","Afternoon skiing/snowboarding","Located in Whistler","All equipment provided"],"description":"<p>The English &amp; Ski winter programme aims to help students develop their English alongside their skiing or snowboarding skills. Based in Whistler, the programme combines language study with an active experience in one of Canada''s best-known mountain destinations.</p><p>Morning English classes provide time to focus on language development. Afternoons are devoted to skiing or snowboarding, allowing students to balance classroom learning with time on the slopes. Equipment is provided as part of the programme.</p><p>Our approach encourages students to build confidence through practice in two different settings. Language learning calls for attention and expression, while winter sports offer opportunities to develop coordination, persistence and a willingness to learn from experience.</p><p>Throughout the programme, the emphasis is on maintaining progress in English while becoming more comfortable on the snow. Students share an active winter experience and develop the confidence to approach both learning and unfamiliar situations with greater independence.</p>","status":"inactive","gallery":[]}');
INSERT OR IGNORE INTO catalog_entities(kind,slug,name,status,category_slug,sort_order,content_json) VALUES ('program','uk-english-foundation','English Foundation Summer','inactive','language-and-activity-camps',3,'{"order":3,"id":"uk-english-foundation","category_slug":"language-and-activity-camps","name":"English Foundation Summer","tagline":"Enhance and improve language skills in a supportive and immersive environment.","image":"","ages":{"min":11,"max":17},"duration":null,"level":"Foundation","price":null,"color":"primary","badges":["Summer","Language"],"highlights":["Dynamic language curriculum focused on speaking and listening.","Enhance and improve student’s language skills.","Supportive and immersive environment.","Includes various activities and excursions."],"description":"<p>The English Foundation Summer programme aims to strengthen students'' English in a supportive and immersive environment. It brings together structured language study, activities and excursions so that learning remains connected to the wider experience of camp life.</p><p>The curriculum covers speaking, listening, grammar, vocabulary, reading and writing. Students work on the different skills that support effective communication, developing their understanding of how English is used as well as their confidence in using it themselves.</p><p>Our approach balances accuracy with participation. Students are encouraged to express ideas, listen to others and build on their existing knowledge, recognising that progress comes through regular practice and a willingness to keep trying.</p><p>Throughout the programme, activities and excursions provide a broader setting for language learning. The focus is on building a stronger foundation in English while helping students become more engaged, confident and independent communicators.</p>","includes":[],"excludes":[],"status":"inactive","gallery":[]}');
INSERT OR IGNORE INTO catalog_entities(kind,slug,name,status,category_slug,sort_order,content_json) VALUES ('program','italy-football-ac-milan','Football with AC Milan','active','soccer-camps',1,'{"order":1,"id":"italy-football-ac-milan","category_slug":"soccer-camps","name":"Football with AC Milan","tagline":"Unparalleled football training under the guidance of AC Milan’s Youth Team and Academy coaches.","image":"/images/09-07-2025-Football_Milan__X0A7085.webp","ages":{"min":"8","max":"16"},"duration":0,"level":"","price":"","color":"danger","badges":["Official"],"highlights":["Unparalleled football training with AC Milan’s Youth Team coaches and official Milan Academy coaches.","Tournaments & Friendly games.","Specialized training for players who are goalkeepers."],"description":"<p>The Football with AC Milan programme aims to help boys and girls aged 8 to 16 develop their football through focused training and match experience. Students have the opportunity to work on their game under the guidance of AC Milan''s Youth Team coaches and official Milan Academy coaches.</p><p>Coaching sessions provide a setting in which players can concentrate on their skills and understand how individual contributions support a team. Specialised training is available for goalkeepers, recognising the particular demands and responsibilities of the position.</p><p>Our approach brings preparation and play together. Tournaments and friendly games give players opportunities to apply what they learn, respond to different situations and develop their understanding of the game through experience.</p><p>Throughout the programme, the emphasis is on commitment, cooperation and a positive attitude towards improvement. Players are encouraged to listen, practise with purpose and show respect for teammates, opponents and coaches as they develop greater confidence on the pitch.</p>","includes":["Individual football coaching","Recordings on camera","Performance certificate","AC Milan’s official kit","FB Accommodations","Special camp excursions"],"excludes":[],"status":"active","schedule":[],"gallery":[]}');
INSERT OR IGNORE INTO catalog_entities(kind,slug,name,status,category_slug,sort_order,content_json) VALUES ('program','spain-soccer-camp','Pro Soccer Camp','inactive','soccer-camps',2,'{"order":2,"id":"spain-soccer-camp","category_slug":"soccer-camps","name":"Pro Soccer Camp","image":"/images/spain_4_g.webp","ages":{"min":8,"max":18},"duration":2,"price":"€3,100","color":"primary","badges":["Sports","Popular"],"highlights":["Train with top coaches","Improve technical skills","Tactical workshops","Visit famous stadiums"],"description":"<p>The Pro Soccer Camp aims to help young football enthusiasts develop their skills while experiencing the football culture that inspires them. Designed for fans of clubs such as FC Barcelona and Real Madrid, the programme combines training, tactical learning and visits to famous stadiums.</p><p>Players train with coaches to strengthen their technical skills and develop a clearer understanding of the game. Tactical workshops encourage them to consider positioning, choices on the ball and how individual actions contribute to a team''s performance.</p><p>Our approach connects purposeful practice with an appreciation of football beyond the training pitch. Stadium visits offer a different perspective on the sport, while coaching activities encourage players to reflect on the skills they want to improve.</p><p>Throughout the camp, players focus on technique, game awareness and working effectively with others. The emphasis is on approaching training with commitment, responding positively to feedback and carrying a sense of respect and teamwork into every session.</p>","status":"inactive","gallery":[]}');
INSERT OR IGNORE INTO catalog_entities(kind,slug,name,status,category_slug,sort_order,content_json) VALUES ('program','canada-adventure-summer','Adventure Summer Camp','inactive','special-interests-camps',2,'{"order":2,"id":"canada-adventure-summer","category_slug":"special-interests-camps","name":"Adventure Summer Camp","image":"/images/canada_2.webp","ages":{"min":12,"max":17},"duration":2,"price":"$3,800","color":"secondary","badges":["Adventure","Summer"],"highlights":["Canoeing in pristine lakes","Hiking in national parks","Wildlife spotting","Campfire stories"],"description":"<p>The Adventure Summer Camp aims to help students discover the outdoors through an active experience in British Columbia. The programme combines exploration, shared activities and time in nature, giving campers opportunities to step beyond their usual surroundings.</p><p>Canoeing on lakes and hiking in national parks introduce different ways to experience the Canadian landscape. Wildlife spotting encourages careful observation, while campfire stories bring the group together to share experiences and enjoy the social side of camp.</p><p>Our approach encourages curiosity, cooperation and respect for the environment. Campers are invited to take an active role in shared experiences, pay attention to their surroundings and recognise the importance of contributing to a group.</p><p>Throughout the programme, outdoor activities provide opportunities to build confidence and independence. The focus is on discovering new interests, developing friendships and approaching unfamiliar experiences with a thoughtful and open attitude.</p>","status":"inactive","gallery":["/images/canada_1.webp","/images/canada_2.webp","/images/canada_3.webp"]}');
INSERT OR IGNORE INTO catalog_entities(kind,slug,name,status,category_slug,sort_order,content_json) VALUES ('program','italy-fashion','Fashion','active','special-interests-camps',3,'{"order":3,"id":"italy-fashion","category_slug":"special-interests-camps","name":"Fashion","tagline":"Immerse yourself in the world of fashion design in the heart of Milan.","image":"/images/53774_6ceb90297448b376.webp","ages":{"min":"15","max":"18"},"duration":0,"level":"","price":"","color":"secondary","badges":["New","Design"],"highlights":["Introduction to product design and brainstorming for innovative ideas.","Use of AI software to develop unique product concepts.","Learn graphic design techniques for detailed sketches.","Culmination with prototyping, transforming digital ideas into tangible creation."],"description":"<p>The Fashion programme aims to help young fashion enthusiasts explore the creative process in the heart of Milan. Students have the opportunity to develop ideas, experiment with design and consider how a concept can become a tangible creation.</p><p>The programme introduces product design and brainstorming as starting points for creative development. Students explore AI software for generating product concepts and use graphic design techniques to communicate their ideas through detailed sketches.</p><p>Our approach connects imagination with the decisions involved in making a design work. Students are encouraged to consider different possibilities, develop a personal direction and refine the way they present their ideas, rather than stopping at their first concept.</p><p>Throughout the programme, the focus moves from initial inspiration towards prototyping. By bringing digital ideas into a physical form, students explore the relationship between creativity and practical development while building a clearer understanding of their interests within fashion.</p>","includes":[],"excludes":[],"status":"active","schedule":[],"gallery":[]}');
INSERT OR IGNORE INTO catalog_entities(kind,slug,name,status,category_slug,sort_order,content_json) VALUES ('program','italy-food','Food','active','special-interests-camps',5,'{"order":5,"id":"italy-food","category_slug":"special-interests-camps","name":"Food","tagline":"Hands-on experience in Italian cooking, baking, and pastry making, in partnership with IN CONGUSTO INSTITUTE.","image":"/images/Kitchen_113.webp","ages":{"min":"15","max":"18"},"duration":0,"level":"","price":"","color":"info","badges":["Partnership","Culinary Arts"],"highlights":["Partnership with IN CONGUSTO INSTITUTE.","Intensive 40-hour programme.","Hands-on experience in Italian cooking, baking, and pastry making.","Exploration of the restaurant business and new culinary formats."],"description":"<p>The Food programme aims to introduce students to Italian gastronomic arts through practical experience in cooking, baking and pastry making. Delivered in partnership with IN CONGUSTO INSTITUTE, the intensive 40-hour programme offers an opportunity to explore both culinary creativity and the wider food industry.</p><p>Hands-on activities give students a practical introduction to preparing food and understanding the care involved in culinary work. Cooking, baking and pastry making provide different ways to explore technique, develop attention to detail and turn ideas into finished dishes.</p><p>Our approach connects kitchen practice with an understanding of food as a professional field. Students also explore the restaurant business and new culinary formats, considering how food experiences are developed beyond the preparation itself.</p><p>Throughout the programme, the emphasis is on participation, thoughtful practice and discovering personal interests. Students can build a clearer picture of the skills involved in gastronomic arts while exploring possible future directions within the food industry.</p>","includes":["Practical and theoretical lessons","Equipment and ingredients","Field trips & excursions","Supplementary activities","Special events","Accommodation","Milan sightseeing","Visit to cheese factory"],"excludes":[],"status":"active","schedule":[],"gallery":["/images/Copia_di_03-07-2025-Kitchen_CongustoIstitute__X0A5580.webp","/images/Copia_di_03-07-2025-Kitchen_CongustoIstitute__X0A6231.webp","/images/Kitchen_110.webp","/images/Kitchen_113.webp","/images/Kitchen_3.webp","/images/Kitchen_82.webp"]}');
INSERT OR IGNORE INTO catalog_entities(kind,slug,name,status,category_slug,sort_order,content_json) VALUES ('program','italy-outdoor-exploration','Outdoor Exploration','active','special-interests-camps',6,'{"order":6,"id":"italy-outdoor-exploration","category_slug":"special-interests-camps","name":"Outdoor Exploration","tagline":"Challenge yourself with thrilling outdoor adventures","image":"/images/exploration_5.webp","ages":{"min":"12","max":"16"},"duration":3,"level":"Intermediate","price":"","color":"secondary","badges":["Adventure","Challenge"],"highlights":["Rock climbing","Whitewater rafting","Mountain biking","Orienteering and navigation skills"],"description":"<p>The Outdoor Exploration programme aims to help teenagers develop confidence through active challenges in the outdoors. Each day introduces an activity that may be entirely new, creating opportunities to explore personal strengths and approach unfamiliar experiences with an open mind.</p><p>Rock climbing, whitewater rafting and mountain biking offer different physical and practical challenges. Orienteering and navigation add another dimension, encouraging students to observe their surroundings and think carefully about the decisions they make.</p><p>Our approach places personal growth alongside adventure. Campers are encouraged to participate with commitment, listen carefully and recognise how preparation and cooperation contribute to shared experiences, while responding constructively when something feels difficult.</p><p>Throughout the programme, the focus is on developing resilience, independence and a willingness to learn. Students explore the relationship between effort and progress, discovering how unfamiliar activities can become opportunities to build confidence and connect with others.</p>","schedule":{"7:00 AM":"Breakfast & briefing","8:00 AM":"Morning adventure activity","12:30 PM":"Lunch (on location)","2:00 PM":"Afternoon expedition","7:30 PM":"Dinner & debrief"},"includes":["All outdoor equipment","Professional guides","Accommodation in lodges","All meals","Safety equipment"],"excludes":["International flights","Personal outdoor gear","Spending money"],"status":"active","gallery":["/images/exploration_1.webp","/images/exploration_2.webp","/images/exploration_3.webp","/images/exploration_4.webp","/images/exploration_5.webp"]}');
INSERT OR IGNORE INTO catalog_entities(kind,slug,name,status,category_slug,sort_order,content_json) VALUES ('program','italy-sea-quest','Sea Quest','trash','special-interests-camps',7,'{"order":7,"id":"italy-sea-quest","category_slug":"special-interests-camps","name":"Sea Quest","tagline":"Two-week sailing expedition along Italy''s stunning coastline","image":"/images/italy_3.webp","ages":{"min":"14","max":"17"},"duration":2,"level":"Advanced","price":"","color":"primary","badges":["Premium","Limited"],"highlights":["Sail around famous islands","Learn core nautical skills","Coastal exploration","Onboard living experience"],"description":"<p>The Sea Quest programme aims to introduce students to sailing through a two-week expedition along the Italian coast. Travelling around well-known islands provides a setting in which campers can discover core nautical skills while experiencing the rhythm of life at sea.</p><p>The voyage combines coastal exploration with practical learning aboard a sailing vessel. Students become familiar with the shared nature of onboard living and the importance of contributing to daily life as part of a group.</p><p>Our approach connects learning with the experience of the journey. Campers are encouraged to observe, ask questions and consider how communication and cooperation support a sailing expedition, while developing a greater awareness of their surroundings.</p><p>Throughout the programme, the emphasis is on building confidence, understanding basic sailing principles and participating responsibly in a shared adventure. The changing coastline offers a continuing opportunity for discovery as students explore new places and develop friendships aboard.</p>","schedule":{"8:00 AM":"Sailing instruction & navigation","10:00 AM":"Set sail","1:00 PM":"Lunch & swimming stop","3:00 PM":"Afternoon sailing","7:30 PM":"Dinner & shore exploration"},"includes":["Private yacht with crew","All sailing instruction","All meals onboard","Snorkeling equipment","Safety gear"],"excludes":["International flights","Shore meals (optional)","Personal sailing gear"],"status":"trash","gallery":[]}');
INSERT OR IGNORE INTO catalog_entities(kind,slug,name,status,category_slug,sort_order,content_json) VALUES ('program','italy-tennis','Tennis','active',NULL,4,'{"order":4,"id":"italy-tennis","category_slug":"","name":"Tennis","tagline":"High-Performance Junior Tennis Camp for elite training in an iconic Italian destination.","image":"/images/Tennis_MG_2934-187__3_.webp","ages":{"min":"","max":""},"duration":0,"level":"High-Performance","price":"","color":"warning","badges":["Elite"],"highlights":["High-level sports training with an educational and stimulating environment.","Elite training in one of Italy’s most iconic tennis destinations.","Develop your game on state-of-the-art courts.","Internal tournaments, and friendly matches."],"description":"<p>The Tennis programme aims to help young players develop their game through high-performance training in an established Italian tennis setting. The camp combines sporting development with an educational and stimulating environment, giving players opportunities to practise with greater purpose.</p><p>Training takes place on modern courts in a destination where professional players and national teams have prepared for competition. Players can concentrate on improving their own game while gaining an appreciation of the commitment associated with sustained sporting development.</p><p>Our approach connects training with opportunities to put learning into practice. Internal tournaments and friendly matches allow players to explore how they respond to different opponents, make decisions during play and maintain concentration throughout a match.</p><p>Throughout the camp, players are encouraged to approach improvement with discipline and a positive attitude. The focus is on developing confidence, learning from experience and showing respect for others, while using training and match play to identify the next steps in their development.</p>","includes":["Individual tennis coaching","30 hours of tennis coaching with experienced coaches","Mental game and tactical workshop","Recordings on camera","Performance certificate","Full board accommodation","Closing award ceremony"],"excludes":[],"status":"active","schedule":[],"gallery":["/images/Tennis_MG_2934-187__1_.webp","/images/Tennis_MG_2934-187__1_.webp","/images/Tennis_MG_2934-187__2_.webp","/images/Tennis_MG_2934-187__2_.webp","/images/Tennis_MG_2934-187__3_.webp","/images/Tennis_MG_2934-187__3_.webp"]}');
INSERT OR IGNORE INTO catalog_entities(kind,slug,name,status,category_slug,sort_order,content_json) VALUES ('program','italy-sailing','Sailing','active',NULL,2,'{"order":2,"id":"italy-sailing","category_slug":"","name":"Sailing","tagline":"A thrilling sailing voyage exploring the stunning islands off Italy’s coast for core nautical skills and teamwork.","image":"/images/sailing_7.webp","ages":{"min":"12","max":"16"},"duration":0,"level":"","price":"","color":"primary","badges":["Adventure"],"highlights":["Extraordinary sailing adventure exploring the stunning islands off Italy’s coast.","Campers learn core nautical skills and experience life aboard 50-foot yachts.","Sail as part of a three-yacht flotilla, guided by experienced instructors.","Participate in interactive lessons on marine life and local history."],"description":"<p>The Sailing programme aims to help 12 to 16-year-olds develop nautical skills, independence and teamwork through a voyage around Italy''s coastal islands. Conducted entirely in English, the experience combines practical sailing with the discovery of new places and life aboard 50-foot yachts.</p><p>British RYA instructors and native English-speaking counsellors lead the programme. Campers sail as part of a three-yacht flotilla, learning through participation while becoming familiar with the cooperation and communication required aboard.</p><p>Our approach connects sailing techniques with personal responsibility. Students are encouraged to contribute to the group, listen carefully and develop self-reliance, while exploring how leadership can involve supporting others as well as making decisions.</p><p>Throughout the voyage, interactive lessons on marine life and local history add context to the places students visit. Campers work towards a sailing certificate of achievement while developing practical experience, stronger communication and a greater appreciation of a shared journey at sea.</p>","includes":[],"excludes":[],"status":"active","schedule":[],"gallery":["/images/sailing_1.webp","/images/sailing_2.webp","/images/sailing_3.webp","/images/sailing_4.webp","/images/sailing_5.webp","/images/sailing_6.webp","/images/sailing_7.webp","/images/sailing_8.webp","/images/sailing_9.webp"]}');
INSERT OR IGNORE INTO catalog_entities(kind,slug,name,status,category_slug,sort_order,content_json) VALUES ('program','uk-young-leader-oxford','Young Leader Program','active','young-leader-program',1,'{"order":1,"id":"uk-young-leader-oxford","category_slug":"young-leader-program","name":"Young Leader Program","tagline":"Young Leaders London in the Heart of Oxford","image":"/images/young_1.webp","ages":{"min":14,"max":18},"duration":0,"price":"","level":"Upper Intermediate to Advanced English","color":"primary","badges":[],"highlights":["Public speaking and presentation English","Time management tasks and scenarios","Negotiation, debate and leadership practice","Global English for future learning"],"description":"<p>Young Leaders London in the heart of Oxford is designed for students aged 14 to 18 with an Upper Intermediate to Advanced level of English. The programme is suited to young people interested in world issues, strengthening their English and developing critical thinking, debating and leadership skills that support future academic study and careers.</p><p>The syllabus combines theory lessons, interactive lectures, project research and real-life case studies for a stimulating and varied learning experience.</p><p>Students build confidence in public speaking and presentations, tackle time management scenarios, and practise negotiation, debating and leadership through practical lessons. They also develop a better understanding of global English and its application to future learning.</p>","includes":[],"excludes":[],"status":"active","gallery":[]}');
INSERT OR IGNORE INTO catalog_entities(kind,slug,name,status,category_slug,sort_order,content_json) VALUES ('program','uk-mini-mba','MINI MBA','active','young-leader-program',2,'{"order":2,"id":"uk-mini-mba","category_slug":"young-leader-program","name":"MINI MBA","tagline":"Introduction to management and business for ages 15–17","image":"/images/young_3_new.webp","ages":{"min":15,"max":17},"duration":0,"price":"","level":"Introductory","color":"secondary","badges":[],"highlights":["Management and business case studies","Introduction to financial statements and accounting","Entrepreneurship and opportunity identification","Organisations, leadership and marketing","Business at Work visits on the three-week course"],"description":"<p>The MINI MBA introduces students aged 15 to 17 to business and management through lectures, discussions, projects and case studies.</p><p><strong>Introduction to Management:</strong> Develop the vocabulary, knowledge and confidence to analyse business reports, debate business issues, research company case studies and present projects.</p><p><strong>Accounting:</strong> Gain an introduction to basic accounting and financial-statement analysis.</p><p><strong>Entrepreneurship:</strong> Explore entrepreneurial thinking, the concept of entrepreneurship and recognising opportunities.</p><p><strong>Organisations:</strong> Consider how organisations have developed and how that history shapes leadership and management in business.</p><p><strong>Marketing:</strong> Use lectures, discussions and short case studies to examine marketing issues and tools in the 21st century.</p><p><strong>Business at Work:</strong> On the three-week course only, visits to operating businesses offer insight into everyday production and management.</p>","includes":[],"excludes":[],"status":"active","gallery":[]}');
INSERT OR IGNORE INTO catalog_entities(kind,slug,name,status,category_slug,sort_order,content_json) VALUES ('program','usa-global-leadership','Global Leadership Training','inactive','young-leader-program',1,'{"order":1,"id":"usa-global-leadership","category_slug":"young-leader-program","name":"Global Leadership Training","image":"/images/usa_2.webp","ages":{"min":15,"max":18},"duration":3,"price":"$4,500","color":"accent","badges":["Leadership","Academic"],"highlights":["Public speaking workshops","Debate and negotiation","Project management","Visits to major organizations"],"description":"<p>The Global Leadership Training programme aims to help students develop the skills to participate confidently in an interconnected world. Workshops and real-world case studies introduce the challenges of communicating ideas, working with others and taking responsibility for shared goals.</p><p>Students explore public speaking, debate and negotiation alongside project management. Each area offers a different perspective on leadership, from explaining a viewpoint clearly to organising work and responding thoughtfully to people with different priorities.</p><p>Our approach connects leadership concepts with situations beyond the classroom. Visits to major organisations provide a wider context for considering how teams operate and how decisions affect the people around them.</p><p>Throughout the programme, students focus on critical thinking, communication and cooperation. They are encouraged to listen as carefully as they speak, support their ideas with reasoning and recognise that effective leadership involves accountability, reflection and respect for others.</p>","status":"inactive","gallery":[]}');
INSERT OR IGNORE INTO catalog_entities(kind,slug,name,status,category_slug,sort_order,content_json) VALUES ('program','switzerland-adventure-camp','Adventure Camp','active','special-interests-camps',3,'{"order":3,"id":"switzerland-adventure-camp","category_slug":"special-interests-camps","name":"Adventure Camp","image":"/images/swiss_2.webp","ages":{"min":"10","max":"16"},"duration":2,"price":"","color":"secondary","badges":["Adventure","Popular"],"highlights":["Mountain hiking","Lake activities","Chocolate & cheese tasting","Team building"],"description":"<p>The Adventure Camp aims to help students discover the Swiss Alps through outdoor activity and shared experiences. The programme brings together mountain exploration, time by the water and opportunities to make new friends in a classic summer camp setting.</p><p>Mountain hiking and lake activities introduce different aspects of the landscape. Chocolate and cheese tasting offer a way to explore local culture, adding variety to an experience that combines physical activity with discovery.</p><p>Our approach places teamwork alongside personal confidence. Group activities encourage campers to communicate, contribute and recognise the value of supporting one another, while taking part in experiences beyond their everyday routines.</p><p>Throughout the camp, the focus is on enjoying the outdoors, exploring new interests and building friendships. Students are encouraged to participate with curiosity, respect their surroundings and develop a greater sense of independence through the daily experiences of camp life.</p>","status":"active","includes":[],"excludes":[],"schedule":[],"tagline":"","level":"","gallery":["/images/swiss_1.webp","/images/swiss_2.webp","/images/swiss_3.webp","/images/swiss_5.webp"]}');
INSERT OR IGNORE INTO catalog_entities(kind,slug,name,status,category_slug,sort_order,content_json) VALUES ('program','switzerland-film-academy','Film Academy Camp','trash','special-interests-camps',2,'{"order":2,"id":"switzerland-film-academy","category_slug":"special-interests-camps","name":"Film Academy Camp","image":"/images/swiss_4.webp","ages":{"min":"14","max":"18"},"duration":3,"price":"","color":"primary","badges":["Creative","Specialty"],"highlights":["Screenwriting","Directing","Cinematography","Editing with pro software"],"description":"<p>The Film Academy Camp aims to introduce aspiring filmmakers to the process of creating a short film. Students explore how an idea develops into a story for the screen, bringing together writing, directing, cinematography and editing in a practical creative experience.</p><p>The programme follows the journey from an initial concept to a finished film. Students write, shoot and edit their work, discovering how decisions about images, performance and sequence influence the way a story is understood.</p><p>Our approach connects creative expression with practical choices. Editing with professional software forms part of the process, while the different stages of production encourage students to plan, communicate and reflect on the relationship between their intentions and the result.</p><p>Throughout the camp, the emphasis is on developing a personal voice and learning through making. Students can explore the roles that interest them, refine their ideas and experience the satisfaction of bringing separate elements together into a film of their own.</p>","status":"trash","includes":[],"excludes":[],"schedule":[],"tagline":"","level":"","gallery":["/images/swiss_4.webp"]}');
INSERT OR IGNORE INTO catalog_entities(kind,slug,name,status,category_slug,sort_order,content_json) VALUES ('program','switzerland-ski-camp','Ski Camp (Winter)','active','special-interests-camps',1,'{"order":1,"id":"switzerland-ski-camp","category_slug":"special-interests-camps","name":"Ski Camp (Winter)","image":"/images/53814_bf0ca3d656de44fd.webp","ages":{"min":"8","max":"17"},"duration":1,"price":"","color":"primary","badges":["Winter","Sports"],"highlights":["Professional ski instruction","Access to top resorts","Après-ski activities","All gear included"],"description":"<p>The Ski Camp aims to help students learn to ski or strengthen their existing skills on Swiss slopes. The winter programme combines professional instruction with the wider experience of spending time in a mountain resort, giving students a focused setting for developing confidence on the snow.</p><p>Professional ski instructors guide the learning, helping students work on their skills through practice. Access to established resorts allows campers to experience the mountain environment, with ski equipment included as part of the programme.</p><p>Our approach encourages patience, concentration and a positive response to challenges. Students are invited to focus on their own progress, recognise the value of careful practice and develop greater confidence as their familiarity with skiing grows.</p><p>Throughout the camp, time on the slopes is complemented by après-ski activities. The emphasis is on combining sporting development with an enjoyable shared winter experience, allowing students to build friendships alongside their confidence in skiing.</p>","status":"active","includes":[],"excludes":[],"schedule":[],"tagline":"","level":"","gallery":["/images/Winter-2.webp","/images/Winter-day-camps-zip-line-1.webp","/images/Winter-day-camps-zip-line-2.webp"]}');
INSERT OR IGNORE INTO catalog_entities(kind,slug,name,status,category_slug,sort_order,content_json) VALUES ('program','uk-academic-architecture','Architecture','active','adult-academic',1,'{"order":1,"id":"uk-academic-architecture","category_slug":"adult-academic","name":"Architecture","tagline":"","image":"/images/uk-academic-architecture.webp","ages":{"min":13,"max":15},"duration":2,"level":"Academic","price":null,"color":"primary","badges":["Academic"],"highlights":["Explore architectural design, technical drawing and the built environment","Examine architectural history, materials and adaptive reuse","Develop a personal design project using practical creative techniques","Strengthen visual communication and critical thinking with tutor feedback"],"description":"<p>The Architecture programme aims to introduce students to the creative and technical thinking behind the built environment. Taking inspiration from Cambridge''s historic and contemporary buildings, students explore how design decisions shape the spaces in which people live, study and connect.</p><p>The programme brings together architectural history, drawing and design principles. Practical design exercises encourage students to observe their surroundings, explore form and function, and consider how materials influence both the appearance and the purpose of a building.</p><p>Our approach connects imagination with thoughtful problem-solving. Students investigate sustainable design and adaptive reuse, considering how existing buildings can meet new needs. Project work and individual feedback support the development of visual communication, critical thinking and a clearer design process.</p><p>Throughout the programme, students work towards expressing and developing their own architectural ideas. The focus is on explaining decisions, testing possibilities and understanding how creative proposals can respond to the needs of people and places, providing a foundation for further exploration of architecture and design.</p>","includes":[],"excludes":[],"status":"active","gallery":[]}');
INSERT OR IGNORE INTO catalog_entities(kind,slug,name,status,category_slug,sort_order,content_json) VALUES ('program','uk-academic-artificial-intelligence','Artificial Intelligence','active','adult-academic',2,'{"order":2,"id":"uk-academic-artificial-intelligence","category_slug":"adult-academic","name":"Artificial Intelligence","tagline":"","image":"/images/uk-academic-artificial-intelligence.webp","ages":{"min":16,"max":18},"duration":2,"level":"Academic","price":null,"color":"primary","badges":["Academic"],"highlights":["Study machine learning, algorithms and neural networks","Explore real-world AI applications through coding and problem-solving","Discuss AI ethics, responsible innovation and societal impact","Develop independent ideas and technical confidence in a guided project"],"description":"<p>The Artificial Intelligence programme aims to introduce students to the ideas behind systems that learn from data. From recommendation systems to robotics and generative AI, students explore how intelligent technologies recognise patterns, support decisions and contribute to different areas of everyday life.</p><p>The programme combines an introduction to machine learning, algorithms and neural networks with coding activities and practical problem-solving. Students investigate the difference between writing instructions for a computer and training a model, considering how data shapes the results a system produces.</p><p>Our approach connects technical understanding with responsible judgement. Discussions explore reliability, bias, privacy and the wider effects of AI, encouraging students to question how a system works as well as whether it is appropriate for a particular task.</p><p>Throughout the programme, guided project work gives students opportunities to develop their own ideas. The focus is on computational thinking, careful reasoning and clear explanation, helping students approach a changing field with curiosity and a stronger understanding of its possibilities and limitations.</p>","includes":[],"excludes":[],"status":"active","gallery":[]}');
INSERT OR IGNORE INTO catalog_entities(kind,slug,name,status,category_slug,sort_order,content_json) VALUES ('program','uk-academic-biology','Biology','inactive','adult-academic',3,'{"order":3,"id":"uk-academic-biology","category_slug":"adult-academic","name":"Biology","tagline":"","image":"/images/uk-academic-biology.webp","ages":{"min":16,"max":18},"duration":2,"level":"Academic","price":null,"color":"primary","badges":["Academic"],"highlights":[],"description":"<p>The Biology programme aims to introduce students to the study of living systems, from the processes within organisms to their relationships with the wider environment. Students explore genetics, ecology and human biology while developing an understanding of how scientific questions are investigated.</p><p>The programme connects these areas through the methods used in the life sciences. Students consider how observations lead to questions, how evidence supports an explanation and why biological ideas need to be examined carefully rather than accepted without enquiry.</p><p>Our approach encourages students to look for connections between different scales of life. Genetics offers a perspective on inheritance, human biology explores the functioning of the body, and ecology considers how organisms interact with one another and their surroundings.</p><p>Throughout the programme, the focus is on scientific curiosity, accurate explanation and thoughtful interpretation. Students develop a foundation for further biological study while becoming more confident in asking questions and considering what the available evidence can tell them.</p>","includes":[],"excludes":[],"status":"inactive","gallery":[]}');
INSERT OR IGNORE INTO catalog_entities(kind,slug,name,status,category_slug,sort_order,content_json) VALUES ('program','uk-academic-biotechnology','Biotechnology','inactive','adult-academic',4,'{"order":4,"id":"uk-academic-biotechnology","category_slug":"adult-academic","name":"Biotechnology","tagline":"","image":"/images/uk-academic-biotechnology.webp","ages":{"min":16,"max":18},"duration":2,"level":"Academic","price":null,"color":"primary","badges":["Academic"],"highlights":[],"description":"<p>The Biotechnology programme aims to introduce students to the ways biological science can be applied to practical challenges. Students explore the relationship between understanding living systems and using that knowledge in medicine, agriculture and environmental work.</p><p>The programme considers biotechnology across these different settings, helping students recognise how a scientific idea can become an application. The focus is on understanding the biological principles involved and the questions that arise when those principles are used for a particular purpose.</p><p>Our approach connects scientific curiosity with thoughtful evaluation. Students are encouraged to consider both the possibilities of an application and the evidence needed to understand its effects, developing the habit of asking how and why a biological approach might be useful.</p><p>Throughout the programme, students build an introductory understanding of an interdisciplinary field. The emphasis is on connecting concepts, explaining ideas clearly and recognising how biological knowledge can contribute to decisions about health, food production and the environment.</p>","includes":[],"excludes":[],"status":"inactive","gallery":[]}');
INSERT OR IGNORE INTO catalog_entities(kind,slug,name,status,category_slug,sort_order,content_json) VALUES ('program','uk-academic-business-management','Business Management','active','adult-academic',5,'{"order":5,"id":"uk-academic-business-management","category_slug":"adult-academic","name":"Business Management","tagline":"","image":"/images/uk-academic-business-management.webp","ages":{"min":13,"max":15},"duration":2,"level":"Academic","price":null,"color":"primary","badges":["Academic"],"highlights":["Learn business strategy, pricing, marketing and management fundamentals","Explore entrepreneurship and how new ventures develop","Analyse real-world business choices through case studies and discussion","Build leadership, teamwork and presentation skills through project work"],"description":"<p>The Business Management programme aims to introduce students to the decisions involved in building and running an organisation. Students explore how businesses create value, understand their customers and respond to changing markets, while developing an appreciation of the relationship between an idea and a workable venture.</p><p>The programme brings together strategy, management, marketing, pricing and leadership. Case studies and collaborative challenges provide opportunities to examine business choices, consider different priorities and explore how resources can be organised to support a goal.</p><p>Our approach combines entrepreneurial thinking with careful analysis. Students investigate product positioning, planning and growth, learning to balance creativity with commercial judgement. Presenting ideas helps them develop clear communication and explain the reasoning behind a proposal.</p><p>Throughout the programme, the focus is on evaluating opportunities, working constructively with others and recognising the consequences of business decisions. Students develop foundations for further study in business, economics or entrepreneurship while becoming more confident in turning broad ideas into a considered plan.</p>","includes":[],"excludes":[],"status":"active","gallery":[]}');
INSERT OR IGNORE INTO catalog_entities(kind,slug,name,status,category_slug,sort_order,content_json) VALUES ('program','uk-academic-chemistry','Chemistry','inactive','adult-academic',6,'{"order":6,"id":"uk-academic-chemistry","category_slug":"adult-academic","name":"Chemistry","tagline":"","image":"/images/uk-academic-chemistry.webp","ages":{"min":16,"max":18},"duration":2,"level":"Academic","price":null,"color":"primary","badges":["Academic"],"highlights":[],"description":"<p>The Chemistry programme aims to introduce students to the principles that explain how substances behave and interact. Through the study of organic and inorganic chemistry, students explore how chemical reactions connect the properties of materials with changes at a molecular level.</p><p>The programme brings together the language and concepts used to describe chemical behaviour. Students consider how different areas of chemistry relate to one another and how a clear understanding of basic principles supports more complex explanations.</p><p>Our approach encourages careful reasoning and attention to detail. Students are invited to distinguish an observation from an explanation, use chemical ideas consistently and consider the evidence behind an account of a reaction or material property.</p><p>Throughout the programme, the focus is on strengthening understanding rather than simply remembering terminology. Students develop a foundation for further study by connecting chemical concepts, explaining processes clearly and approaching unfamiliar questions in a structured and thoughtful way.</p>","includes":[],"excludes":[],"status":"inactive","gallery":[]}');
INSERT OR IGNORE INTO catalog_entities(kind,slug,name,status,category_slug,sort_order,content_json) VALUES ('program','uk-academic-computer-science','Computer Science','active','adult-academic',7,'{"order":7,"id":"uk-academic-computer-science","category_slug":"adult-academic","name":"Computer Science","tagline":"","image":"/images/uk-academic-computer-science.webp","ages":{"min":13,"max":15},"duration":2,"level":"Academic","price":null,"color":"primary","badges":["Academic"],"highlights":["Develop programming, logic and computational-thinking fundamentals","Practise designing, testing and improving algorithms","Explore software development and age-appropriate advanced computing topics","Apply problem-solving skills in practical projects and discussions"],"description":"<p>The Computer Science programme aims to help students understand how software turns ideas into working systems. Students explore programming, computational thinking and logical problem-solving, developing a foundation for understanding the technologies that shape everyday life.</p><p>Practical exercises introduce the process of breaking a problem into smaller steps, designing a solution and writing and testing code. Students consider how programs are structured and why the choice of an algorithm can influence how effectively a task is completed.</p><p>Our approach combines technical practice with clear reasoning. Depending on the learning group, topics may include data structures, algorithmic efficiency, software engineering and introductory artificial intelligence. Project work and discussion encourage students to explain their decisions and reflect on ways to improve a solution.</p><p>Throughout the programme, the emphasis is on persistence, creativity and an organised approach to unfamiliar challenges. Students strengthen their analytical skills while developing the confidence to investigate computing in greater depth, whether as a personal interest or a possible direction for future study.</p>","includes":[],"excludes":[],"status":"active","gallery":[]}');
INSERT OR IGNORE INTO catalog_entities(kind,slug,name,status,category_slug,sort_order,content_json) VALUES ('program','uk-academic-creative-writing','Creative Writing','inactive','adult-academic',8,'{"order":8,"id":"uk-academic-creative-writing","category_slug":"adult-academic","name":"Creative Writing","tagline":"","image":"/images/uk-academic-creative-writing.webp","ages":{"min":13,"max":15},"duration":2,"level":"Academic","price":null,"color":"primary","badges":["Academic"],"highlights":[],"description":"<p>The Creative Writing programme aims to help students develop their storytelling skills and begin to recognise their own writing voice. Students explore fiction, poetry and other creative forms, considering how language can communicate an idea, create an atmosphere or shape a reader''s response.</p><p>The programme connects creative exploration with attention to the choices a writer makes. Students consider the relationship between what they want to express and the form they choose, developing greater awareness of how words and structure work together.</p><p>Our approach encourages experimentation alongside reflection. Students are invited to try different possibilities, recognise the qualities they value in their work and consider how an initial idea might be developed into a more deliberate piece of writing.</p><p>Throughout the programme, the emphasis is on imagination, clarity and a willingness to refine. Students build confidence in expressing a perspective of their own while developing a stronger foundation for continued creative practice.</p>","includes":[],"excludes":[],"status":"inactive","gallery":[]}');
INSERT OR IGNORE INTO catalog_entities(kind,slug,name,status,category_slug,sort_order,content_json) VALUES ('program','uk-academic-criminology','Criminology','inactive','adult-academic',9,'{"order":9,"id":"uk-academic-criminology","category_slug":"adult-academic","name":"Criminology","tagline":"","image":"/images/uk-academic-criminology.webp","ages":{"min":16,"max":18},"duration":2,"level":"Academic","price":null,"color":"primary","badges":["Academic"],"highlights":[],"description":"<p>The Criminology programme aims to introduce students to the study of criminal behaviour and the systems through which societies respond to crime. Students explore the relationship between individual actions, social conditions and the operation of justice systems.</p><p>Discussion and analysis provide ways to examine different explanations and perspectives. Students consider how questions about crime can involve both an understanding of behaviour and an awareness of the wider social issues surrounding it.</p><p>Our approach encourages careful reasoning rather than quick conclusions. Students are invited to distinguish evidence from assumption, consider how a viewpoint is supported and recognise that explanations of crime and justice may involve competing interpretations.</p><p>Throughout the programme, the focus is on developing analytical awareness and clear communication. Students strengthen their ability to examine complex social questions thoughtfully, providing an introductory foundation for further exploration of criminology, justice and related areas of study.</p>","includes":[],"excludes":[],"status":"inactive","gallery":[]}');
INSERT OR IGNORE INTO catalog_entities(kind,slug,name,status,category_slug,sort_order,content_json) VALUES ('program','uk-academic-economics','Economics','active','adult-academic',10,'{"order":10,"id":"uk-academic-economics","category_slug":"adult-academic","name":"Economics","tagline":"","image":"/images/uk-academic-economics.webp","ages":{"min":13,"max":18},"duration":2,"level":"Academic","price":null,"color":"primary","badges":["Academic"],"highlights":["Examine markets, supply and demand, trade and inflation","Investigate economic policy, global development and inequality","Build confidence interpreting data, graphs and economic evidence","Develop critical arguments through seminars and practical research"],"description":"<p>The Economics programme aims to help students understand how individuals, businesses and governments make choices. Students explore the relationship between economic ideas and the questions they raise in everyday life, from changing prices and international trade to growth and inequality.</p><p>The programme introduces supply and demand, market structures, inflation and economic policy. Seminars, research and case-study discussions encourage students to examine incentives and trade-offs, while interpreting data and graphs helps connect theory with evidence. London''s role in global finance provides a wider context for considering markets and investment decisions.</p><p>Our approach develops reasoned judgement. Students are encouraged to question assumptions, compare explanations and consider how a policy can affect different groups, rather than treating an economic argument as a single fixed answer.</p><p>Throughout the programme, students practise developing an evidence-based viewpoint and communicating it clearly. The emphasis is on analytical thinking, careful interpretation and understanding connections, building foundations for further study in economics, finance, politics or business.</p>","includes":[],"excludes":[],"status":"active","gallery":[]}');
INSERT OR IGNORE INTO catalog_entities(kind,slug,name,status,category_slug,sort_order,content_json) VALUES ('program','uk-academic-engineering','Engineering','active','adult-academic',11,'{"order":11,"id":"uk-academic-engineering","category_slug":"adult-academic","name":"Engineering","tagline":"","image":"/images/uk-academic-engineering.webp","ages":{"min":13,"max":18},"duration":2,"level":"Academic","price":null,"color":"primary","badges":["Academic"],"highlights":["Discover engineering design, mechanics, materials and structures","Explore robotics, electronics or control systems through age-appropriate topics","Apply engineering reasoning to practical challenges and projects","Develop teamwork, creativity and systematic problem-solving"],"description":"<p>The Engineering programme aims to introduce students to the process of turning scientific ideas into practical solutions. Students explore how mathematics, mechanics and materials help engineers understand a challenge and develop designs that respond to it.</p><p>Analytical exercises and practical project work introduce the stages of identifying a problem, developing a design and testing its performance. Depending on the learning group, topics may include structures, electronics, robotics, fluid mechanics, control systems and the use of computing or machine learning in engineering.</p><p>Our approach connects creative ideas with systematic evaluation. Students are encouraged to consider why a design might work, recognise the limits of an initial proposal and use evidence to guide improvements. Discussion, independent research and feedback support this process.</p><p>Throughout the programme, the focus is on problem-solving, clear technical communication and a willingness to refine. Students develop a foundation for further exploration of civil, mechanical, electrical and emerging engineering fields while becoming more confident in explaining the decisions behind a practical solution.</p>","includes":[],"excludes":[],"status":"active","gallery":[]}');
INSERT OR IGNORE INTO catalog_entities(kind,slug,name,status,category_slug,sort_order,content_json) VALUES ('program','uk-academic-english-literature','English Literature','inactive','adult-academic',12,'{"order":12,"id":"uk-academic-english-literature","category_slug":"adult-academic","name":"English Literature","tagline":"","image":"/images/uk-academic-english-literature.webp","ages":{"min":16,"max":18},"duration":2,"level":"Academic","price":null,"color":"primary","badges":["Academic"],"highlights":[],"description":"<p>The English Literature programme aims to help students engage more closely with classic and modern literary works. Students explore how texts create meaning and how interpretation can develop through careful reading, reflection and critical discussion.</p><p>The programme places literary study alongside the process of forming an argument. Students consider how details within a text support a reading and how different interpretations can reveal aspects of the same work.</p><p>Our approach encourages attention to language and openness to other perspectives. Students are invited to move beyond an immediate reaction, examine the choices that shape a piece of writing and explain how those choices influence their understanding.</p><p>Throughout the programme, the focus is on thoughtful interpretation and clear expression. Students develop confidence in discussing literature, supporting their views with textual evidence and responding constructively to ideas that differ from their own, building a foundation for further literary study.</p>","includes":[],"excludes":[],"status":"inactive","gallery":[]}');
INSERT OR IGNORE INTO catalog_entities(kind,slug,name,status,category_slug,sort_order,content_json) VALUES ('program','uk-academic-history','History','inactive','adult-academic',13,'{"order":13,"id":"uk-academic-history","category_slug":"adult-academic","name":"History","tagline":"","image":"/images/uk-academic-history.webp","ages":{"min":16,"max":18},"duration":2,"level":"Academic","price":null,"color":"primary","badges":["Academic"],"highlights":[],"description":"<p>The History programme aims to help students understand how influential events, people and movements have shaped the past. Students explore historical questions through research and critical analysis, considering how accounts of the past are developed and interpreted.</p><p>The programme connects the study of events with the evidence used to explain them. Students consider relationships between actions and consequences, the contexts in which people made decisions and the different perspectives through which a historical development can be understood.</p><p>Our approach encourages curiosity alongside careful judgement. Students are invited to question an account, consider its supporting evidence and recognise that understanding the past involves interpretation as well as knowledge of what happened.</p><p>Throughout the programme, the emphasis is on building reasoned explanations and communicating them clearly. Students strengthen their ability to connect ideas, evaluate arguments and approach unfamiliar historical questions with an organised and reflective method.</p>","includes":[],"excludes":[],"status":"inactive","gallery":[]}');
INSERT OR IGNORE INTO catalog_entities(kind,slug,name,status,category_slug,sort_order,content_json) VALUES ('program','uk-academic-international-relations','International Relations','inactive','adult-academic',14,'{"order":14,"id":"uk-academic-international-relations","category_slug":"adult-academic","name":"International Relations","tagline":"","image":"/images/uk-academic-international-relations.webp","ages":{"min":13,"max":18},"duration":2,"level":"Academic","price":null,"color":"primary","badges":["Academic"],"highlights":[],"description":"<p>The International Relations programme aims to introduce students to the ideas and relationships that shape global affairs. Students explore international politics, diplomacy, international law and conflict resolution, considering how decisions extend beyond national boundaries.</p><p>The programme connects these areas through the challenges of cooperation and disagreement. Students examine how different priorities can influence relationships and how diplomatic and legal approaches contribute to attempts to resolve shared problems.</p><p>Our approach encourages students to consider more than one perspective. They are invited to question assumptions, distinguish an argument from the evidence supporting it and recognise the complexity involved in decisions affecting different societies.</p><p>Throughout the programme, the focus is on critical analysis, clear explanation and thoughtful engagement with world issues. Students develop a foundation for further study while strengthening their ability to discuss international questions with greater awareness and respect for differing viewpoints.</p>","includes":[],"excludes":[],"status":"inactive","gallery":[]}');
INSERT OR IGNORE INTO catalog_entities(kind,slug,name,status,category_slug,sort_order,content_json) VALUES ('program','uk-academic-law','Law','inactive','adult-academic',15,'{"order":15,"id":"uk-academic-law","category_slug":"adult-academic","name":"Law","tagline":"","image":"/images/uk-academic-law.webp","ages":{"min":13,"max":18},"duration":2,"level":"Academic","price":null,"color":"primary","badges":["Academic"],"highlights":[],"description":"<p>The Law programme aims to introduce students to legal systems and the principles that guide judicial decisions. Students explore how legal reasoning differs from an immediate personal opinion and why a structured argument matters when considering questions of justice.</p><p>The programme connects an understanding of legal principles with the process of applying them. Students consider how rules, interpretation and reasoning contribute to a legal position, developing greater awareness of the relationship between a principle and a particular question.</p><p>Our approach encourages precision, consistency and careful explanation. Students are invited to identify assumptions, examine the basis of an argument and consider how different interpretations can lead to different conclusions.</p><p>Throughout the programme, the focus is on developing a clear and disciplined way of thinking. Students build an introductory foundation for legal study while strengthening the analytical and communication skills needed to engage thoughtfully with complex questions.</p>","includes":[],"excludes":[],"status":"inactive","gallery":[]}');
INSERT OR IGNORE INTO catalog_entities(kind,slug,name,status,category_slug,sort_order,content_json) VALUES ('program','uk-academic-mathematics','Mathematics','inactive','adult-academic',16,'{"order":16,"id":"uk-academic-mathematics","category_slug":"adult-academic","name":"Mathematics","tagline":"","image":"/images/uk-academic-mathematics.webp","ages":{"min":15,"max":18},"duration":2,"level":"Academic","price":null,"color":"primary","badges":["Academic"],"highlights":[],"description":"<p>The Mathematics programme aims to strengthen students'' reasoning through the study of algebra, calculus, statistics and problem-solving. Students explore how mathematical ideas connect and how a clear method can make an unfamiliar question more manageable.</p><p>The programme places understanding alongside technique. Students consider why a method works, what its results mean and how different mathematical approaches can be used to describe a relationship or investigate a problem.</p><p>Our approach encourages persistence and precision. Students are invited to break a challenge into smaller steps, check the assumptions they use and recognise that revisiting an unsuccessful approach can be an important part of making progress.</p><p>Throughout the programme, the emphasis is on explaining reasoning clearly and developing confidence with mathematical ideas. Students build a foundation for further study while strengthening the habits of careful analysis, logical organisation and thoughtful problem-solving.</p>","includes":[],"excludes":[],"status":"inactive","gallery":[]}');
INSERT OR IGNORE INTO catalog_entities(kind,slug,name,status,category_slug,sort_order,content_json) VALUES ('program','uk-academic-medicine','Medicine','active','adult-academic',17,'{"order":17,"id":"uk-academic-medicine","category_slug":"adult-academic","name":"Medicine","tagline":"","image":"/images/uk-academic-medicine.webp","ages":{"min":13,"max":18},"duration":2,"level":"Academic","price":null,"color":"primary","badges":["Academic"],"highlights":["Explore human anatomy, physiology, genetics and biomedical science","Understand disease, diagnostics and the immune response","Investigate contemporary medical research and approaches to treatment","Develop clinical reasoning, ethical awareness and research skills"],"description":"<p>The Medicine programme aims to introduce students to the science of the human body and the questions involved in maintaining health. Students explore anatomy, physiology and biomedical science, considering how cells, organs and body systems work together.</p><p>The programme develops this foundation through the study of disease, genetics, infection and the immune response. Case-based activities and academic discussion introduce clinical reasoning, while topics such as cancer biology, biomarkers and personalised medicine illustrate the changing directions of medical research.</p><p>Our approach connects scientific understanding with the human responsibilities of healthcare. Students consider patient care and ethical decisions alongside the evidence used to investigate illness, recognising that medical questions require careful judgement as well as technical knowledge.</p><p>Throughout the programme, guided research and feedback support curiosity, analytical thinking and clear communication. Students build an introductory foundation for exploring medicine, medical science and related pathways, while developing a more informed understanding of the questions that healthcare professionals and researchers face.</p>","includes":[],"excludes":[],"status":"active","gallery":[]}');
INSERT OR IGNORE INTO catalog_entities(kind,slug,name,status,category_slug,sort_order,content_json) VALUES ('program','uk-academic-natural-sciences','Natural Sciences','inactive','adult-academic',18,'{"order":18,"id":"uk-academic-natural-sciences","category_slug":"adult-academic","name":"Natural Sciences","tagline":"","image":"/images/uk-academic-natural-sciences.webp","ages":{"min":13,"max":15},"duration":2,"level":"Academic","price":null,"color":"primary","badges":["Academic"],"highlights":[],"description":"<p>The Natural Sciences programme aims to introduce students to the connections between biology, chemistry and physics. Rather than viewing these subjects in isolation, students explore how different scientific perspectives can contribute to an understanding of the same world.</p><p>The programme uses interdisciplinary study to connect ideas across the sciences. Students consider how the properties of matter, physical processes and living systems relate, developing a broader view of the questions scientific study can address.</p><p>Our approach encourages curiosity and flexible thinking. Students are invited to recognise common principles, consider how an explanation changes with the scale of a question and use scientific reasoning to make connections between familiar and unfamiliar concepts.</p><p>Throughout the programme, the emphasis is on understanding relationships and explaining them clearly. Students develop foundations for further scientific study while strengthening their ability to approach a question from more than one disciplinary perspective.</p>","includes":[],"excludes":[],"status":"inactive","gallery":[]}');
INSERT OR IGNORE INTO catalog_entities(kind,slug,name,status,category_slug,sort_order,content_json) VALUES ('program','uk-academic-philosophy-politics-and-economics','Philosophy, Politics and Economics','inactive','adult-academic',19,'{"order":19,"id":"uk-academic-philosophy-politics-and-economics","category_slug":"adult-academic","name":"Philosophy, Politics and Economics","tagline":"","image":"/images/uk-academic-philosophy-politics-and-economics.webp","ages":{"min":16,"max":18},"duration":2,"level":"Academic","price":null,"color":"primary","badges":["Academic"],"highlights":[],"description":"<p>The Philosophy, Politics and Economics programme aims to help students explore the connections between ideas, institutions and decisions. Students consider how philosophical questions, political thought and economic reasoning can offer different perspectives on the same social challenge.</p><p>The programme brings these subjects together through critical analysis. Students examine how an argument is constructed, what assumptions it depends on and how a change in perspective can influence the conclusions people reach.</p><p>Our approach encourages intellectual curiosity and reasoned disagreement. Students are invited to distinguish a claim from its justification, compare viewpoints fairly and consider how values and practical consequences both contribute to a decision.</p><p>Throughout the programme, the focus is on developing clear thinking and a considered voice. Students strengthen their ability to connect concepts, explain their reasoning and engage thoughtfully with questions that do not always have a single straightforward answer.</p>","includes":[],"excludes":[],"status":"inactive","gallery":[]}');
INSERT OR IGNORE INTO catalog_entities(kind,slug,name,status,category_slug,sort_order,content_json) VALUES ('program','uk-academic-physics','Physics','inactive','adult-academic',20,'{"order":20,"id":"uk-academic-physics","category_slug":"adult-academic","name":"Physics","tagline":"","image":"/images/uk-academic-physics.webp","ages":{"min":13,"max":18},"duration":2,"level":"Academic","price":null,"color":"primary","badges":["Academic"],"highlights":[],"description":"<p>The Physics programme aims to introduce students to the principles used to explain the physical world. From mechanics and forces to modern physical theory, students explore how scientific ideas describe relationships and help make sense of observed behaviour.</p><p>The programme connects the study of physical laws with the reasoning behind them. Students consider how a model represents a situation, how an explanation relates to evidence and why the assumptions used in a problem matter.</p><p>Our approach encourages clear thinking and a willingness to question. Students are invited to connect mathematical relationships with physical meaning, consider where an explanation applies and approach unfamiliar problems by identifying the principles involved.</p><p>Throughout the programme, the emphasis is on understanding rather than memorising isolated facts. Students develop a foundation for further study while strengthening their confidence in interpreting ideas, following a logical method and explaining the physical reasoning behind a conclusion.</p>","includes":[],"excludes":[],"status":"inactive","gallery":[]}');
INSERT OR IGNORE INTO catalog_entities(kind,slug,name,status,category_slug,sort_order,content_json) VALUES ('program','uk-academic-psychology','Psychology','inactive','adult-academic',21,'{"order":21,"id":"uk-academic-psychology","category_slug":"adult-academic","name":"Psychology","tagline":"","image":"/images/uk-academic-psychology.webp","ages":{"min":13,"max":18},"duration":2,"level":"Academic","price":null,"color":"primary","badges":["Academic"],"highlights":[],"description":"<p>The Psychology programme aims to introduce students to the study of cognition, emotion and human behaviour. Students explore how psychological questions are investigated and how research can contribute to an understanding of the ways people think, feel and act.</p><p>The programme connects these themes with the methods used in psychological enquiry. Students consider how a question can be studied, what evidence might support an explanation and why the interpretation of findings requires care.</p><p>Our approach encourages curiosity without relying on quick assumptions about people. Students are invited to distinguish an everyday impression from a research-based explanation and consider how different perspectives can contribute to an understanding of behaviour.</p><p>Throughout the programme, the emphasis is on critical thinking, clear reasoning and respect for complexity. Students develop an introductory foundation for further psychological study while becoming more confident in examining claims and communicating a considered viewpoint.</p>","includes":[],"excludes":[],"status":"inactive","gallery":[]}');
INSERT OR IGNORE INTO catalog_entities(kind,slug,name,status,category_slug,sort_order,content_json) VALUES ('program','uk-academic-veterinary-studies','Veterinary Studies','inactive','adult-academic',22,'{"order":22,"id":"uk-academic-veterinary-studies","category_slug":"adult-academic","name":"Veterinary Studies","tagline":"","image":"/images/uk-academic-veterinary-studies.webp","ages":{"min":15,"max":18},"duration":2,"level":"Academic","price":null,"color":"primary","badges":["Academic"],"highlights":[],"description":"<p>The Veterinary Studies programme aims to introduce students to veterinary medicine, animal care and animal welfare. Students explore the relationship between understanding an animal''s health and considering its needs, developing an introductory view of the responsibilities involved in veterinary work.</p><p>The programme connects basic veterinary principles with the wider context of caring for animals. Students consider how knowledge, observation and careful judgement contribute to decisions about health and wellbeing.</p><p>Our approach places thoughtful enquiry alongside respect for animal welfare. Students are encouraged to ask questions, recognise the limits of an initial impression and consider why a responsible approach to care depends on both scientific understanding and attention to the animal.</p><p>Throughout the programme, the focus is on building a foundation for further exploration. Students develop curiosity, clear communication and a more informed understanding of the field while considering their own interest in animal health and care.</p>","includes":[],"excludes":[],"status":"inactive","gallery":[]}');
INSERT OR IGNORE INTO catalog_entities(kind,slug,name,status,category_slug,sort_order,content_json) VALUES ('program','tennis-academy','Tennis Academy','active','tennis',1,'{"order":1,"id":"tennis-academy","category_slug":"tennis","name":"Tennis Academy","tagline":"Train with purpose, build match confidence and grow your game on and off the court.","image":"/images/imported-9b759cf6c4187e.webp","ages":{"min":9,"max":17},"duration":1,"level":"Beginner to Advanced","price":null,"color":"success","badges":["Tennis","Skill Development"],"highlights":["Focused tennis coaching to develop technique, movement and match confidence.","Ability-aware drills, tactical challenges and purposeful match practice.","Develop consistency, court positioning and decision-making under pressure.","Build sportsmanship, resilience and friendships through an active camp experience."],"description":"<p>The Tennis programme aims to provide players of all levels, from beginner to advanced, with the opportunity to train through a fully professional and detailed programme. At the start of each week, all students are assessed and placed into tennis class groups based on their ability.</p><p>Our professional tennis coaching team have achieved a high standard in the game themselves and, in addition to coaching a range of skills and techniques, they also mentor students on every aspect of the game, including agility, fitness and mental attitude.</p><p>Our methodology combines the four pillars of professional player development: Technical, Tactical, Physical and Mental. All teaching, drills and exercises incorporate these four pillars to form a single integrated system, based on the commonalities of top players today. We encourage every player, regardless of level or age, to improve and maximise their potential. To do so, players must demonstrate complete commitment and a willingness to push themselves to reach higher levels within a short timeframe. Most importantly, we support the development of essential performance behaviours such as discipline, resilience, handling adversity, responsibility, accountability, proper focus, and respect for other players and staff.</p><p>Throughout the week, the tennis summer camp programme emphasises coaching aimed at improving technique through better stance, increasing power in strokes, and enhancing shot selection, alongside boosting consistency. Players will also focus on speed, fitness, hand-eye coordination, agility, key strokes, tactical incorporation of strokes, self-analysis, mental perseverance and goal setting.</p>","includes":["Tennis technique and footwork development","Ability-appropriate tactical coaching and match-play practice","Individual improvement goals and practical feedback","Sportsmanship, confidence and teamwork activities"],"excludes":[],"status":"active","schedule":[],"gallery":["/images/imported-b4eecf3804ce9b.webp","/images/imported-5acb0b681a0332.webp"]}');
INSERT OR IGNORE INTO catalog_entities(kind,slug,name,status,category_slug,sort_order,content_json) VALUES ('program','uk-soccer-club-experience','UK Soccer Academy & Club Experience','active','soccer-camps',3,'{"order":3,"id":"uk-soccer-club-experience","category_slug":"soccer-camps","name":"UK Soccer Academy & Club Experience","tagline":"Build your skills, train with ambition and explore the football cultures that inspire champions.","image":"/images/uk-soccer-arsenal-day-hero.webp","ages":{"min":null,"max":null},"duration":null,"level":"All skill levels (grouped by ability)","price":null,"color":"primary","badges":["Soccer","UK Football"],"highlights":["Technical sessions focused on first touch, passing, dribbling and finishing.","Small-sided games and tactical challenges to develop match intelligence.","Strength, teamwork and confidence through age- and ability-appropriate coaching.","Discover the football traditions of Arsenal, Liverpool FC, Manchester City and Paris Saint-Germain."],"description":"<p>The UK Soccer Academy &amp; Club Experience programme aims to help young players develop their technique, confidence and understanding of football. The programme brings together focused practice and game situations, encouraging players to approach improvement with commitment and enjoy the shared experience of training with others.</p><p>Sessions focus on first touch, passing, dribbling and finishing, alongside position-specific exercises and passing combinations. Age- and ability-appropriate coaching helps players connect individual skills with the movement and decisions involved in playing as a team.</p><p>Our approach combines technical development with tactical awareness, teamwork and resilience. Small-sided games and tactical challenges encourage players to read situations, make decisions under pressure and reflect on how their choices influence play. Football traditions associated with Arsenal, Liverpool FC, Manchester City and Paris Saint-Germain offer points of inspiration.</p><p>Throughout the programme, the emphasis is on purposeful practice, fair play and a positive response to feedback. Players work on consistency and match confidence while developing respect for teammates, opponents and coaches, with opportunities to form friendships through a shared interest in football.</p>","includes":["Structured football skill-development sessions","Technical, tactical and team-based exercises","Friendly games and skill challenges","Player progress feedback, subject to local camp arrangements"],"excludes":[],"status":"active","schedule":[],"gallery":["/images/uk-soccer-arsenal-day-hero.webp","/images/uk-soccer-camp-group-hallway.webp","/images/uk-soccer-camp-group-outdoor.webp","/images/uk-soccer-training-session.webp","/images/uk-soccer-training-huddle.webp","/images/soccer_2.webp","/images/soccer_3.webp"]}');
INSERT OR IGNORE INTO catalog_entities(kind,slug,name,status,category_slug,sort_order,content_json) VALUES ('program','germany-lindenberg-teenagers','Lindenberg German for Teenagers','active','german-language-courses',2,'{"order":2,"id":"germany-lindenberg-teenagers","category_slug":"german-language-courses","name":"Lindenberg German for Teenagers","tagline":"Build German confidence through year-round study and residential life in the Alpine foothills.","image":"/images/humboldt-lindenberg.webp","ages":{"min":13,"max":17},"duration":null,"level":"A1–C2","price":null,"color":"primary","badges":["German","Year-round"],"highlights":["Ages 13–17 · year-round","30 lessons per week · 45 minutes each","Residential accommodation and full board","Activities and excursions; optional winter sports"],"description":"<p>The Lindenberg German programme aims to help students aged 13 to 17 develop their language skills through year-round residential study. Set in the foothills of the Alps, the school combines a focused learning environment with opportunities to explore the surrounding region.</p><p>Students take 30 German lessons per week, with each lesson lasting 45 minutes. Teaching is supported by placement into an appropriate learning group, allowing students to work at a level that reflects their existing knowledge and next learning goals.</p><p>Our approach connects classroom progress with everyday communication. Living and learning on the same campus creates opportunities to use German with international peers, strengthening confidence, independence and a willingness to participate beyond formal lessons.</p><p>Throughout the week, daily activities and excursions complement language study. Residential accommodation and full board are included, while summer host-family stays are an alternative for this age group. Optional winter skiing and snowboarding lessons offer another way to enjoy the Alpine setting.</p>","includes":["German lessons and course materials","Course certificate","Residential accommodation and full board","24-hour supervision","Daily activities and scheduled excursions"],"excludes":[],"status":"active","schedule":[],"gallery":[]}');
INSERT OR IGNORE INTO catalog_entities(kind,slug,name,status,category_slug,sort_order,content_json) VALUES ('program','germany-bad-schussenried-teenagers','Bad Schussenried German for Teenagers','active','german-language-courses',3,'{"order":3,"id":"germany-bad-schussenried-teenagers","category_slug":"german-language-courses","name":"Bad Schussenried German for Teenagers","tagline":"Combine intensive German study with sport and residential summer life in southern Germany.","image":"/images/humboldt-bad-schussenried.webp","ages":{"min":13,"max":17},"duration":null,"level":"A1–C1","price":null,"color":"primary","badges":["German","Summer"],"highlights":["Ages 13–17 · summer","30 German lessons per week","On-campus accommodation and full board","Sports facilities, daily activities and excursions"],"description":"<p>The Bad Schussenried German programme aims to help teenagers aged 13 to 17 develop their German through an active residential summer experience. Classrooms, accommodation and leisure facilities share one campus, creating a convenient setting for focused learning and daily participation.</p><p>Students attend 30 German lessons each week, with learning organised around their language level. Regular classroom study gives students time to strengthen their understanding and develop the confidence to contribute, ask questions and communicate with greater clarity.</p><p>Our approach brings language learning together with the social experience of camp. Roommates are selected with attention to age, language level and different native languages, encouraging students to use German when sharing their everyday experiences.</p><p>Throughout the programme, daily activities and excursions provide opportunities to continue learning outside the classroom. Indoor and outdoor sports facilities add variety to the week, while residential accommodation, full board and supervision support a structured summer stay.</p>","includes":["German lessons and course materials","Course certificate","Residential accommodation and full board","24-hour supervision","Daily activities and scheduled excursions"],"excludes":[],"status":"active","schedule":[],"gallery":[]}');
INSERT OR IGNORE INTO catalog_entities(kind,slug,name,status,category_slug,sort_order,content_json) VALUES ('program','germany-berlin-teenager','Berlin German Summer for Teenagers','active','german-language-courses',4,'{"order":4,"id":"germany-berlin-teenager","category_slug":"german-language-courses","name":"Berlin German Summer for Teenagers","tagline":"Develop German through intensive lessons and supervised discovery of the capital.","image":"/images/humboldt-berlin-teenager.webp","ages":{"min":14,"max":17},"duration":null,"level":"A1–B2","price":null,"color":"primary","badges":["German","Summer"],"highlights":["Ages 14–17 · summer · A1–B2","30 German lessons per week","Two-, three- or five-week course options","Residential package with activities and excursions"],"description":"<p>The Berlin German Summer programme aims to help students aged 14 to 17 strengthen their language skills while discovering Germany''s capital. A central residential setting connects intensive study with opportunities to explore the city''s history, culture and everyday life.</p><p>Students attend 30 lessons per week from Monday to Friday, with content adapted to teenage learners. Classes cover levels A1 to B2 and encourage active participation through varied learning activities and regular opportunities to speak German.</p><p>Our approach combines classroom learning with shared daily experiences. Students live and study in the same youth hostel near Berlin Central Station, allowing language practice to continue through meals, group activities and conversations with international peers.</p><p>Throughout the week, supervised activities and excursions introduce different aspects of Berlin and its surroundings. Accommodation, full board and supervision are included. The programme offers two-, three- or five-week stays according to the selected course period, giving students a clear balance of study and discovery.</p>","includes":["German lessons and course materials","Course certificate","Residential accommodation and full board","24-hour supervision","Daily activities and scheduled excursions"],"excludes":[],"status":"active","schedule":[],"gallery":[]}');
INSERT OR IGNORE INTO catalog_entities(kind,slug,name,status,category_slug,sort_order,content_json) VALUES ('program','germany-cologne-teenagers','Cologne German Summer for Teenagers','active','german-language-courses',5,'{"order":5,"id":"germany-cologne-teenagers","category_slug":"german-language-courses","name":"Cologne German Summer for Teenagers","tagline":"Learn German in a residential summer programme beside the Rhine.","image":"/images/humboldt-cologne.webp","ages":{"min":14,"max":18},"duration":null,"level":"A1–B2","price":null,"color":"primary","badges":["German","Summer"],"highlights":["Ages 14–18 · summer · A1–B2","30 lessons per week; two- or four-week stays","Twin rooms with en-suite bathrooms","Full board, supervision, activities and excursions"],"description":"<p>The Cologne German Summer programme aims to help students aged 14 to 18 develop their German while experiencing a lively city on the Rhine. The programme combines intensive language study with residential life and opportunities to discover Cologne''s culture and surroundings.</p><p>Students attend 30 lessons per week from Monday to Friday, with classes available from A1 to B2. Teaching is adapted to teenage learners and includes varied activities with an emphasis on speaking, encouraging students to take an active role in their progress.</p><p>Our approach connects learning with everyday communication. Lessons and accommodation are based at the Cologne City Hostel in Deutz, where twin rooms with private bathrooms provide a convenient setting for sharing daily life with international students.</p><p>Throughout the programme, daily leisure activities and organised excursions extend the learning experience. Full board and supervision are included, and two- or four-week stays are available. Time exploring Cologne and nearby destinations gives students further opportunities to use German beyond the classroom.</p>","includes":["German lessons and course materials","Course certificate","Residential accommodation and full board","24-hour supervision","Daily activities and scheduled excursions"],"excludes":[],"status":"active","schedule":[],"gallery":[]}');
INSERT OR IGNORE INTO catalog_entities(kind,slug,name,status,category_slug,sort_order,content_json) VALUES ('program','germany-duesseldorf-teenagers','Düsseldorf German Summer for Teenagers','active','german-language-courses',6,'{"order":6,"id":"germany-duesseldorf-teenagers","category_slug":"german-language-courses","name":"Düsseldorf German Summer for Teenagers","tagline":"Strengthen German through intensive study and summer experiences along the Rhine.","image":"/images/humboldt-dusseldorf.webp","ages":{"min":14,"max":18},"duration":null,"level":"A1–B2","price":null,"color":"primary","badges":["German","Summer"],"highlights":["Ages 14–18 · summer · A1–B2","30 lessons per week; two- or four-week stays","Riverside residence with en-suite twin rooms","Full board, activities and supervised excursions"],"description":"<p>The Düsseldorf German Summer programme aims to help students aged 14 to 18 build language confidence through study and cultural discovery. Based beside the Rhine, the programme connects a residential learning environment with opportunities to explore the city and its surroundings.</p><p>Students take 30 lessons per week from Monday to Friday. Classes span A1 to B2 and use varied learning activities with regular speaking practice, encouraging both beginners and learners with previous knowledge to participate at an appropriate level.</p><p>Our approach connects language development with the practical experience of living with others. Classrooms and accommodation are in the Düsseldorf City Hostel, with modern twin rooms and private bathrooms keeping study and daily routines conveniently together.</p><p>Throughout the week, activities and excursions provide opportunities to communicate beyond lessons. The riverfront and nearby city sights offer a setting for exploration, while two- or four-week residential packages include full board and supervision. Shared experiences help students build independence, cooperation and international friendships.</p>","includes":["German lessons and course materials","Course certificate","Residential accommodation and full board","24-hour supervision","Daily activities and scheduled excursions"],"excludes":[],"status":"active","schedule":[],"gallery":[]}');
INSERT OR IGNORE INTO catalog_entities(kind,slug,name,status,category_slug,sort_order,content_json) VALUES ('program','germany-munich-teenagers','Munich German Summer for Teenagers','active','german-language-courses',7,'{"order":7,"id":"germany-munich-teenagers","category_slug":"german-language-courses","name":"Munich German Summer for Teenagers","tagline":"Balance German language development with residential summer life in Bavaria.","image":"/images/humboldt-munich.webp","ages":{"min":15,"max":18},"duration":null,"level":"A1–B2","price":null,"color":"primary","badges":["German","Summer"],"highlights":["Ages 15–18 · summer · A1–B2","30 lessons per week","Two-, three- or five-week course options","Residential package; shared bathroom facilities"],"description":"<p>The Munich German Summer programme aims to help students aged 15 to 18 develop their language skills while discovering the Bavarian capital. The programme combines intensive lessons with a residential campus setting close to the city, offering a balance of focused study and cultural exploration.</p><p>Students attend 30 German lessons per week, with classes covering levels A1 to B2. Teaching is adapted to teenage learners and encourages participation through varied activities and opportunities to practise speaking.</p><p>Our approach brings learning into the daily experience of camp. Students live and study at the Don Bosco youth hostel, where shared residential life and group activities provide further reasons to communicate in German and cooperate with international peers.</p><p>Throughout the programme, leisure activities and supervised excursions add variety to the week. Accommodation and full board are included, with shared bathroom facilities at the residence. Two-, three- or five-week stays are available according to the course period, allowing students to explore Munich while maintaining a purposeful study routine.</p>","includes":["German lessons and course materials","Course certificate","Residential accommodation and full board","24-hour supervision","Daily activities and scheduled excursions"],"excludes":[],"status":"active","schedule":[],"gallery":[]}');
INSERT OR IGNORE INTO catalog_entities(kind,slug,name,status,category_slug,sort_order,content_json) VALUES ('program','austria-vienna-teenagers','Vienna German Summer for Teenagers','active','german-language-courses',8,'{"order":8,"id":"austria-vienna-teenagers","category_slug":"german-language-courses","name":"Vienna German Summer for Teenagers","tagline":"Study German while exploring Vienna’s culture and the outdoor spaces of the Danube.","image":"/images/humboldt-vienna.webp","ages":{"min":14,"max":18},"duration":null,"level":"A1–B2","price":null,"color":"primary","badges":["German","Summer"],"highlights":["Ages 14–18 · summer · Vienna, Austria","30 lessons per week · A1–B2","Two- or four-week residential stays","Full board, activities and supervised excursions"],"description":"<p>The Vienna German Summer programme aims to help students aged 14 to 18 develop their language skills in Austria''s capital. The programme combines structured lessons with residential life and opportunities to experience the city''s cultural attractions and green spaces.</p><p>Students take 30 German lessons each week from Monday to Friday. Classes cover A1 to B2 and use age-appropriate learning activities with an emphasis on speaking, encouraging students to participate and develop greater confidence in communication.</p><p>Our approach connects language study with everyday experience. Students live and learn at the Vienna-Brigittenau youth guest house, with twin rooms and private bathrooms. Its location near the Danube and Danube Island offers a balance between city exploration and outdoor recreation.</p><p>Throughout the programme, daily activities and organised excursions give students further opportunities to use German and connect with their peers. Two- or four-week stays include accommodation, full board and supervision, supporting a summer experience that brings learning, independence and discovery together.</p>","includes":["German lessons and course materials","Course certificate","Residential accommodation and full board","24-hour supervision","Daily activities and scheduled excursions"],"excludes":[],"status":"active","schedule":[],"gallery":[]}');
INSERT OR IGNORE INTO catalog_entities(kind,slug,name,status,category_slug,sort_order,content_json) VALUES ('program','germany-lindenberg-juniors','Lindenberg German for Juniors','active','german-language-courses',9,'{"order":9,"id":"germany-lindenberg-juniors","category_slug":"german-language-courses","name":"Lindenberg German for Juniors","tagline":"Discover German through age-appropriate study and year-round residential activities.","image":"/images/humboldt-lindenberg.webp","ages":{"min":10,"max":12},"duration":null,"level":"A1–C2","price":null,"color":"primary","badges":["German","Year-round"],"highlights":["New junior age range: 10–12","Year-round · 25 lessons per week","On-campus accommodation and full board","Supervised activities and excursions"],"description":"<p>The Lindenberg Junior German programme aims to help children aged 10 to 12 build confidence in German within a year-round residential setting. The campus in the Alpine foothills brings classrooms, accommodation and leisure facilities together, giving younger learners a structured place to study and participate.</p><p>Children attend 25 German lessons per week, with each lesson lasting 45 minutes. Learning is organised according to language level, allowing students to develop their understanding and communication at a pace suited to their starting point.</p><p>Our approach connects language learning with supportive daily routines and interaction with international peers. Residential life gives children opportunities to practise German, contribute to shared activities and gradually become more comfortable expressing themselves.</p><p>Throughout the programme, daily activities and excursions complement classroom study. On-campus accommodation, full board and supervision are included, helping children enjoy a balanced experience of learning and discovery while developing independence, friendships and a positive attitude towards trying something new.</p>","includes":["German lessons and course materials","Course certificate","Residential accommodation and full board","24-hour supervision","Daily activities and scheduled excursions"],"excludes":[],"status":"active","schedule":[],"gallery":[]}');
INSERT OR IGNORE INTO catalog_entities(kind,slug,name,status,category_slug,sort_order,content_json) VALUES ('program','germany-bad-schussenried-juniors','Bad Schussenried German for Juniors','active','german-language-courses',10,'{"order":10,"id":"germany-bad-schussenried-juniors","category_slug":"german-language-courses","name":"Bad Schussenried German for Juniors","tagline":"Build German confidence through junior lessons, residential routines and active summer days.","image":"/images/humboldt-bad-schussenried.webp","ages":{"min":10,"max":12},"duration":null,"level":"A1–C1","price":null,"color":"primary","badges":["German","Summer"],"highlights":["New junior age range: 10–12","Summer · 25 German lessons per week","Residential accommodation and full board","Activities, sports facilities and excursions"],"description":"<p>The Bad Schussenried Junior German programme aims to help children aged 10 to 12 develop their language skills through a residential summer experience. Set within a campus combining classrooms, accommodation and extensive leisure facilities, the programme supports learning alongside play and discovery.</p><p>Children take 25 German lessons each week, with study organised around their language level. Age-appropriate learning gives students opportunities to participate, practise communication and become more comfortable using German with other learners.</p><p>Our approach brings classroom progress together with everyday experience. Shared residential life encourages children to communicate, listen to one another and develop independence, with roommates selected according to age, level and different native languages.</p><p>Throughout the week, activities and excursions complement the language course. Indoor and outdoor sports facilities offer different ways to take part, while accommodation, full board and supervision support the daily routine. The focus is on helping children build confidence, enjoy learning and form friendships through an active summer stay.</p>","includes":["German lessons and course materials","Course certificate","Residential accommodation and full board","24-hour supervision","Daily activities and scheduled excursions"],"excludes":[],"status":"active","schedule":[],"gallery":[]}');
INSERT OR IGNORE INTO catalog_entities(kind,slug,name,status,category_slug,sort_order,content_json) VALUES ('program','germany-reimlingen-juniors','Reimlingen German Summer for Children','active','german-language-courses',11,'{"order":11,"id":"germany-reimlingen-juniors","category_slug":"german-language-courses","name":"Reimlingen German Summer for Children","tagline":"Learn German through child-focused lessons and outdoor discovery in rural Bavaria.","image":"/images/humboldt-reimlingen.webp","ages":{"min":8,"max":12},"duration":null,"level":"A1–B1","price":null,"color":"primary","badges":["German","Summer"],"highlights":["New age range: 8–12 · summer","25 lessons per week · A1–B1","Two- or four-week residential stays","Horse riding available at an additional fee"],"description":"<p>The Reimlingen German Summer programme aims to help children aged 8 to 12 develop their language skills in a welcoming rural setting. Based at Tagungshaus Reimlingen near Nördlingen, the programme brings learning and residential life together within parkland surroundings.</p><p>Children attend 25 lessons each week from Monday to Friday. Classes cover A1 to B1 and are adapted to younger learners, using varied activities and regular speaking opportunities to encourage participation and build confidence.</p><p>Our approach connects classroom learning with shared experiences. Children practise communicating with international peers, develop independence through daily routines and learn the value of cooperation. Accommodation, full board and supervision support their time away from home.</p><p>Throughout the programme, daily activities and excursions provide opportunities to explore and use German beyond lessons. Sports and outdoor play add variety, while optional horse-riding lessons can be booked for an additional fee. Two- or four-week stays offer a balance of language development, friendship and discovery.</p>","includes":["German lessons and course materials","Course certificate","Residential accommodation and full board","24-hour supervision","Daily activities and scheduled excursions"],"excludes":[],"status":"active","schedule":[],"gallery":[]}');
INSERT OR IGNORE INTO catalog_entities(kind,slug,name,status,category_slug,sort_order,content_json) VALUES ('program','germany-berlin-mitte-adults','Berlin-Mitte German for Adults','active','german-language-courses',12,'{"order":12,"id":"germany-berlin-mitte-adults","category_slug":"german-language-courses","name":"Berlin-Mitte German for Adults","tagline":"Develop German for study, work or everyday life in central Berlin.","image":"/images/humboldt-berlin-mitte-adults.webp","ages":{"min":18,"max":null},"duration":null,"level":"A1–C2","price":null,"color":"primary","badges":["German","Year-round"],"highlights":["Ages 18+ · year-round · A1–C2","Intensive course: 30 lessons per week","Residential and host-family options","TestDaF and telc examination centre"],"description":"<p>The Berlin-Mitte German programme aims to help adults aged 18 and over develop their language skills through year-round study in Germany''s capital. The central location combines a focused learning environment with opportunities to experience Berlin''s cultural and everyday life.</p><p>The intensive course offers 30 lessons per week, with levels from A1 to C2. Short- and long-term study options allow learners to work towards their own goals, while small classes support participation and regular communication.</p><p>Our approach connects structured learning with practical immersion. Students can continue using German through meals, activities and conversations with international peers. Residential accommodation and host-family options offer different ways to shape the experience according to individual preferences.</p><p>Throughout the programme, organised activities and opportunities to explore Berlin extend learning beyond the classroom. The institute is also a TestDaF and telc examination centre. Residential packages with full board are available, supporting a study experience that combines language development with greater independence and cultural understanding.</p>","includes":["German lessons and course materials","Course certificate","Residential packages available with accommodation and full board"],"excludes":[],"status":"active","schedule":[],"gallery":[]}');
INSERT OR IGNORE INTO catalog_entities(kind,slug,name,status,category_slug,sort_order,content_json) VALUES ('program','germany-constance-adults','Constance German for Adults','active','german-language-courses',13,'{"order":13,"id":"germany-constance-adults","category_slug":"german-language-courses","name":"Constance German for Adults","tagline":"Combine intensive German learning with life beside Lake Constance.","image":"/images/humboldt-constance-adults.webp","ages":{"min":18,"max":null},"duration":null,"level":"A1–C1","price":null,"color":"primary","badges":["German","Year-round"],"highlights":["Ages 18+ · year-round · A1–C1","Intensive course: 30 lessons per week","On-campus single and twin rooms","TestDaF and telc examination centre"],"description":"<p>The Constance German programme aims to help adults aged 18 and over strengthen their German through year-round study by Lake Constance. The university town provides a setting where language learning can be connected with cultural discovery and everyday communication.</p><p>The intensive course offers 30 lessons per week, with the location''s published course overview covering A1 to C1. Small classes encourage participation, while short- and long-term study options allow learners to pursue different language goals.</p><p>Our approach combines classroom study with opportunities to use German throughout the day. Residential accommodation is in the same building as the classrooms, with single and twin rooms featuring private bathrooms. Shared meals and interaction with other learners extend language practice beyond formal lessons.</p><p>Throughout the programme, after-class activities and the lakeside setting provide a wider context for learning. Residential packages with full board are available, and the institute is a TestDaF and telc examination centre. Students can build language confidence while developing a more independent experience of living and studying in Germany.</p>","includes":["German lessons and course materials","Course certificate","Residential packages available with accommodation and full board"],"excludes":[],"status":"active","schedule":[],"gallery":[]}');
INSERT OR IGNORE INTO catalog_entities(kind,slug,name,status,category_slug,sort_order,content_json) VALUES ('program','germany-berlin-mitte-executives','Berlin-Mitte German for Executives','active','german-language-courses',14,'{"order":14,"id":"germany-berlin-mitte-executives","category_slug":"german-language-courses","name":"Berlin-Mitte German for Executives","tagline":"Develop job-related German through individual tuition shaped around professional goals.","image":"/images/humboldt-berlin-mitte-executives.webp","ages":{"min":27,"max":null},"duration":null,"level":"A1–C2","price":null,"color":"primary","badges":["German","Year-round"],"highlights":["Ages 27+ · year-round · A1–C2","One-to-one tuition: 30 or 40 lessons per week","Content tailored to professional language needs","Residential or tuition-only course options"],"description":"<p>The Berlin-Mitte German for Executives programme aims to help professionals aged 27 and over develop German for their working lives. Available year-round, the programme offers focused individual tuition within a central Berlin setting.</p><p>Students choose one-to-one intensive courses with 30 or 40 lessons per week, each lasting 45 minutes. Content is tailored to the participant''s needs, allowing learning to concentrate on the language skills and communication priorities most relevant to their professional goals.</p><p>Our approach connects intensive study with practical immersion. Individual teaching provides a focused setting for questions and refinement, while conversations and shared daily experiences create opportunities to continue using German outside lessons.</p><p>Throughout the programme, participants can combine language development with an experience of Berlin''s cultural life. Residential packages include accommodation, full board, activities and excursions, while tuition-only options include weekday lunch. The emphasis is on purposeful study, clear communication and making effective use of the time available.</p>","includes":["German lessons and course materials","Course certificate","Residential packages available with accommodation and full board"],"excludes":[],"status":"active","schedule":[],"gallery":[]}');
INSERT OR IGNORE INTO catalog_entities(kind,slug,name,status,category_slug,sort_order,content_json) VALUES ('program','germany-constance-executives','Constance German for Executives','active','german-language-courses',15,'{"order":15,"id":"germany-constance-executives","category_slug":"german-language-courses","name":"Constance German for Executives","tagline":"Focus on professional German through personalised tuition beside Lake Constance.","image":"/images/humboldt-constance-executives.webp","ages":{"min":27,"max":null},"duration":null,"level":"A1–C2","price":null,"color":"primary","badges":["German","Year-round"],"highlights":["Ages 27+ · year-round · A1–C2","One-to-one tuition: 30 or 40 lessons per week","Teaching tailored to professional goals","Residential or tuition-only course options"],"description":"<p>The Constance German for Executives programme aims to help professionals aged 27 and over strengthen the German they need for work. Available year-round, the course combines individual teaching with a lakeside setting suited to focused study and time away from everyday routines.</p><p>Participants choose 30 or 40 one-to-one lessons per week, with each lesson lasting 45 minutes. Teaching is tailored to individual needs, allowing students to concentrate on their professional communication priorities and develop the areas that matter most to their goals.</p><p>Our approach connects personalised tuition with opportunities for everyday language use. Shared meals, conversations and residential life can extend practice beyond the classroom, helping participants build confidence in communicating with greater clarity and independence.</p><p>Throughout the programme, students can balance intensive study with the cultural and recreational opportunities around Lake Constance. Residential packages include accommodation, full board, activities and excursions, while tuition-only options include weekday lunch. The focus remains on purposeful progress through a programme shaped around the individual.</p>","includes":["German lessons and course materials","Course certificate","Residential packages available with accommodation and full board"],"excludes":[],"status":"active","schedule":[],"gallery":[]}');
