INSERT OR IGNORE INTO site_documents(key,content_json) VALUES ('camp_memories','{"title":"Go Campers Memories","show_facebook":true,"items":[{"image":"uk-football-camp-stadium-visit.webp","caption":"Football camp memories — UK","country":"United Kingdom","is_active":true,"in_slider":true},{"image":"ski-camp-friends-on-the-slopes.webp","caption":"Ski camp — on the slopes","country":"","is_active":false,"in_slider":false},{"image":"ski-camp-snow-day.webp","caption":"Ski camp — a day in the snow","country":"","is_active":false,"in_slider":false},{"image":"switzerland-adventure-camp-mountain-friends.webp","caption":"Switzerland adventure camp","country":"Switzerland","is_active":true,"in_slider":true},{"image":"switzerland-adventure-camp-paragliding.webp","caption":"Paragliding — Switzerland adventure camp","country":"Switzerland","is_active":true,"in_slider":true},{"image":"uk-adventure-kids-camp-london-friends.webp","caption":"Friends in London — UK adventure kids camp","country":"United Kingdom","is_active":true,"in_slider":true},{"image":"uk-adventure-kids-camp-london-group.webp","caption":"Exploring London — UK adventure kids camp","country":"United Kingdom","is_active":true,"in_slider":true},{"image":"germany-camp-berlin-handstands.webp","caption":"Summer memories in Germany","country":"Germany","is_active":true,"in_slider":true},{"image":"germany-camp-friends-selfie.webp","caption":"Camp friendships — Germany","country":"Germany","is_active":true,"in_slider":true},{"image":"germany-camp-lakeside-friends.webp","caption":"Lakeside memories — Germany","country":"Germany","is_active":true,"in_slider":true},{"image":"switzerland-camp-friends-together.webp","caption":"Camp friendships — Switzerland","country":"Switzerland","is_active":true,"in_slider":true},{"image":"germany-adventure-summer-camp-climbing.webp","caption":"Climbing — Germany adventure summer camp","country":"Germany","is_active":true,"in_slider":true},{"image":"switzerland-camp-lakeside-group.webp","caption":"Lakeside memories — Switzerland","country":"Switzerland","is_active":true,"in_slider":true},{"image":"switzerland-adventure-camp-canoeing.webp","caption":"Canoeing — Switzerland adventure camp","country":"Switzerland","is_active":true,"in_slider":true},{"image":"italy-culture-camp-rome-group.webp","caption":"Exploring Rome — Italy culture camp","country":"Italy","is_active":true,"in_slider":true},{"image":"germany-camp-brandenburg-gate.webp","caption":"Exploring Berlin — Germany camp","country":"Germany","is_active":true,"in_slider":true},{"image":"germany-camp-berlin-world-clock.webp","caption":"Berlin memories — Germany camp","country":"Germany","is_active":true,"in_slider":true},{"image":"fashion-camp-design-workshop.webp","caption":"Fashion camp — design workshop","country":"","is_active":true,"in_slider":true},{"image":"fashion-camp-portfolio-workshop.webp","caption":"Fashion camp — portfolio workshop","country":"","is_active":true,"in_slider":true},{"image":"germany-partner-facilities-dining-hall.webp","caption":"Our partner facilities — dining hall, Germany","country":"Germany","is_active":true,"in_slider":true},{"image":"germany-partner-facilities-indoor-pool.webp","caption":"Our partner facilities — indoor pool, Germany","country":"Germany","is_active":true,"in_slider":true},{"image":"germany-summer-camp-cycling.webp","caption":"Cycling at summer camp — Germany","country":"Germany","is_active":true,"in_slider":true},{"image":"WhatsApp_Image_2026-10-29_at_14_51_00_bec792038e80a9ea.webp","caption":"Camp","country":"","is_active":true,"in_slider":true},{"image":"uk-soccer-arsenal-day-hero.webp","caption":"Memories 2026 football","country":"United Kingdom","is_active":true,"in_slider":true},{"image":"WhatsApp_Image_2026-10-29_at_14_52_55_5e7b0f66c90e73c3.webp","caption":"Memories 2022 adventure","country":"Germany","is_active":true,"in_slider":true},{"image":"WhatsApp_Image_2026-10-29_at_14_54_47_7a12b1b4f7cda31e.webp","caption":"Memories Adventure 2024","country":"Germany","is_active":true,"in_slider":true},{"image":"WhatsApp_Image_2026-10-29_at_14_55_40_bc8b45a6326c0572.webp","caption":"Memories Adventure 2024","country":"Germany","is_active":true,"in_slider":true},{"image":"WhatsApp_Image_2026-10-29_at_14_56_48_2e0a017665944518.webp","caption":"Memories Adventure 2022","country":"Germany","is_active":true,"in_slider":true}]}');
INSERT OR IGNORE INTO site_documents(key,content_json) VALUES ('faq','[{"question":"How can I choose the right Summer Camp for my child?","answer":"<p>It''s a question many parents struggle with. Some believe it is best to let kids roam and play in a way they rarely do these days. It takes them away from computers, TV, and other high-tech time-suckers, swapping them for conversation, fun, and games in a natural, multinational setting. And perhaps most important, camps are no-parent- zones. \"Kids have to learn how to separate from their families and become resilient and independent. Camp gives them a safe way to take these steps<br><br>Children are ready for camp experience away from home by age 9, especially if they''ve experienced day programs before. You just might have to give your child (and yourself) a little push.<br><br>What should you look for? While there are specific qualities that make some camps better for a certain child than others (a kid who loves art, for instance, might not be a good fit at a place that''s all about horses)<br><br></p>\r\n<p>Key Elements when choosing a camp</p>\r\n<ul>\r\n<li><strong>A history.</strong>&nbsp;A camp that is operating for decades, especially with same staff means something. In today''s world, a camp simply couldn''t stay in business for generations if it were unsafe or poorly run.</li>\r\n<li><strong>A philosophy.&nbsp;</strong>Does it focus on sports? Arts? Leadership? How is this philosophy integrated into its programs?</li>\r\n<li><strong>An emphasis on creating multinational community.&nbsp;</strong>Effective camps pay great attention to big mix of different nationalities and place children together observing their integration.</li>\r\n<li><strong>A well-trained staff.</strong>&nbsp;Staff ratio for children from 8 to 12 is normally 1 to 5. In older groups it may be one to 12 or 15.</li>\r\n<li><strong>Big variety of activity choices.</strong>&nbsp;Your child will feel more independent if he can choose some activities. Therefore a camp with big variety of actives is recommended.</li>\r\n<li><strong>Communications with your child.</strong>&nbsp;Many camps don''t allow cell phones or calls home. Good camps send frequent updates, though, and have kids write emails or Skype at given certain times previously planned. You have to respect this! To let go and help your child to integrate. Still, what if you (or your child) can''t stand the thought of being so detached? Well, perhaps camp isn''t the right fit. Or maybe that''s precisely why you need it. \"If you are successful as a parent, your child is going to leave you at some point. A child''s first experience away from you is part of the process of parenting and should be a happy, exciting growth experience for him and for you as well.</li>\r\n<li><strong>Accreditation.</strong> You probably assume that all children''s summer camps must meet standards. Check if your chosen camp is accredited by well-known organizations. Such International Organizations conduct on-site visits and reviews programs, facilities, as well as operating staff. Accreditation is the best evidence that a camp has made a commitment to health and safety. Always ask about this.</li>\r\n</ul>"},{"question":"What actions are taken to ensure camper safety and wellbeing?","answer":"<p>The safety and wellbeing of campers is the most essential part of the summer programs.<br><br>They are cared for from the moment they arrive at the destination airport, until the summer camp is over. All our camps are in residential schools and are 24 hours supervised by specially trained counselors, who provide s optimum guidance and care.<br><br>Special attention for first - time - away experience of our junior clients, who are best to place in small centers, with the facilities of very close supervision, well performed by teachers and activity leaders. Ratio is one leader for every 5 children- sleep in dormitories.</p>"},{"question":"How should I prepare my child for camp?","answer":"<ul>\r\n<li>Label everything that your child is taking with them with a fabric marker or iron-on label.</li>\r\n<li>Make sure all health forms are completed. It is important to provide the camp all the necessary information, including potentially embarrassing things such as sleep walking or bed wetting.</li>\r\n<li>Have your child spend a night or two with a friend or grandparent so that he / she can experience sleeping away from home before camp.</li>\r\n<li>Make sure your child can manage basic personal hygiene such as showering, brushing teeth and changing clothes. Children need to know how to select appropriate clothing, make a bed with clean sheets, put clothes away, handle laundry etc.</li>\r\n<li>Discuss with your child what will happen at camp and encourage him / her to get excited about the experience he / she will have. Camp is often a child''s first step towards independence and plays an important role in their development.</li>\r\n</ul>"},{"question":"What should my child bring to camp?","answer":"<ul>\r\n<li>Night clothes</li>\r\n<li>Dressing Gown</li>\r\n<li>Slippers</li>\r\n<li>Sufficient underwear for a 14 night stay</li>\r\n<li>14 Pairs of socks (including plenty of spares)</li>\r\n<li>Trousers</li>\r\n<li>Swimwear</li>\r\n<li>Shorts</li>\r\n<li>T-Shirts</li>\r\n<li>Long sleeve tops</li>\r\n<li>Tracksuit or similar</li>\r\n<li>Jumper/Sweatshirt/Fleece</li>\r\n<li>Waterproof jacket/Anorak</li>\r\n<li>Waterproof trousers or trousers that can get muddy</li>\r\n<li>Disco clothes</li>\r\n<li>Two towels (one for swimming and one for washing)</li>\r\n<li>Trainers or substantial footwear</li>\r\n<li>Old shoes (for muddy or wet activities)</li>\r\n<li>Sunglasses</li>\r\n<li>Toiletries:, Wash bag, Toothbrush, Toothpaste, Flannel, Soap, Shower Gel, deodorant, Hair products (shampoo / conditioner), Hair brush, Hair ties, insect repellent and sun cream</li>\r\n<li>Other:</li>\r\n<li>Book to read</li>\r\n<li>Bag for dirty clothing</li>\r\n</ul>\r\n<p><strong>Please note that there are no laundry facilities at the camp.</strong></p>"},{"question":"Will my child be supervised at all times?","answer":"<p>Yes, your child will be supervised at all times, and will be assigned a Peak Leader to look after his / her welfare during the day and night. One Peak Leader is assigned to every FIVE children according to gender. Children are not permitted to go off the site unless accompanied by a member of staff.</p>"},{"question":"What type of food will be provided?","answer":"<p>Camps pay good attention to any special dietary requirements. They must be notified at least two weeks prior to arrival. Mainly they aim to provide all children with a healthy, balanced and high-energy diet during the course of their stay. Vegetarian or No pork options are available can be catered for.</p>"},{"question":"Can my child bring a mobile phone / computer console etc?","answer":"<p>In our experience it is not advisable for children to bring these items with them as they will be too busy to use them. We take all next of kin details, so if contact with parents / guardians is necessary, this can be arranged by telephone.</p>"},{"question":"Do I need to provide pocket money?","answer":"<p>Its parent&rsquo;s choice to provide pocket money for their child though it is highly recommended to allow them to handle money by themselves.</p>"},{"question":"What if my child requires medication whilst on their stay?","answer":"<p>Camp must be notified in advance of any medical complaints or illnesses and treatments required during child''s stay. Therefore completion of the health forms is very important. Full records of treatment will be documented and parents / guardians will always be alerted in an emergency.</p>"},{"question":"How will my child be entertained in the evening?","answer":"<p>Each camp operates an evening entertainment programme ranging from film nights to discos, talent shows or quizzes.</p>"},{"question":"Will my child need any particular clothing or equipment?","answer":"<p>All camps provide you with list of all items that your child may need according time and type of activates and the frequency they do the laundry.</p>"}]');
